BEGIN;

CREATE TEMP TABLE grammar_content_seed (
  seed_key TEXT PRIMARY KEY,
  grammar_point TEXT NOT NULL,
  canonical_form TEXT NOT NULL,
  sense_key TEXT NOT NULL UNIQUE,
  form_group_slug TEXT,
  point_type TEXT NOT NULL,
  primary_node_slug TEXT NOT NULL,
  secondary_node_slugs TEXT[] NOT NULL DEFAULT '{}',
  sub_category TEXT NOT NULL,
  core_meaning TEXT NOT NULL,
  natural_translation TEXT NOT NULL,
  structure TEXT NOT NULL,
  usage_notes TEXT NOT NULL,
  practicality TEXT NOT NULL,
  spoken_or_written TEXT NOT NULL,
  jlpt_level TEXT NOT NULL,
  common_mistakes JSONB NOT NULL,
  base_type TEXT NOT NULL,
  required_form TEXT NOT NULL,
  scenes TEXT[] NOT NULL,
  registers TEXT[] NOT NULL,
  stage_slug TEXT NOT NULL,
  module_slug TEXT NOT NULL,
  sort_order INTEGER NOT NULL,
  prerequisite_seed_keys TEXT[] NOT NULL DEFAULT '{}',
  examples JSONB NOT NULL
) ON COMMIT DROP;

