  {"seed_key":"gp_ext_zuni","grammar_point":"〜ずに","canonical_form":"〜ずに","sense_key":"zuni_without_doing","form_group_slug":"zuni","point_type":"grammar_pattern","primary_node_slug":"time_and_sequence","secondary_node_slugs":["main_subordinate_clauses","written"],"sub_category":"书面不做前项","core_meaning":"较书面地表示不进行前项而进行后项。","natural_translation":"没有……就……","structure":"Vない形去ない + ずに；する→せずに","usage_notes":"意义接近「〜ないで」，但更正式、书面；「する」是不规则的「せずに」。","practicality":"A","spoken_or_written":"written","jlpt_level":"N3","common_mistakes":["不要说「しずに」，正确形式是「せずに」。"],"base_type":"verb","required_form":"ない形词干","scenes":["workplace","school","daily_life"],"registers":["formal","written"],"stage_slug":"functional_patterns","module_slug":"time_cause_condition","sort_order":70,"prerequisite_seed_keys":["gp_nai_form","gp_ext_naide_without"],"examples":[{"jp":"彼は何も言わずに会議室を出ました。","zh":"他什么也没说就离开了会议室。","scene":"workplace","register":"written"},{"jp":"説明書を読まずに操作するのは危険です。","zh":"不看说明书就操作很危险。","scene":"daily_life","register":"formal"},{"jp":"休まずに最後まで走り続けた。","zh":"没有休息，一直跑到了最后。","scene":"school","register":"written"}]},
  {"seed_key":"gp_ext_sugiru","grammar_point":"〜すぎる","canonical_form":"〜すぎる","sense_key":"sugiru_excess","form_group_slug":"sugiru","point_type":"grammar_pattern","primary_node_slug":"comparison_degree_scope","secondary_node_slugs":["adverb_predicate_collocations"],"sub_category":"过度","core_meaning":"表示动作或性质超过合适程度。","natural_translation":"太……／过于……","structure":"Vます去ます/い形容词去い/な形容词词干 + すぎる","usage_notes":"通常带负面或需要调整的含义；「いい」变为「よすぎる」。","practicality":"S","spoken_or_written":"both","jlpt_level":"N4","common_mistakes":["い形容词要去掉「い」，不能说「高いすぎる」。"],"base_type":"clause","required_form":"动词ます词干或形容词词干","scenes":["daily_life","shopping","workplace"],"registers":["casual","polite"],"stage_slug":"functional_patterns","module_slug":"comparison_inference","sort_order":40,"prerequisite_seed_keys":["gp_masu_form","gp_i_adjective_past"],"examples":[{"jp":"昨日は少し飲みすぎました。","zh":"昨天稍微喝多了。","scene":"daily_life","register":"polite"},{"jp":"このかばんは私には高すぎる。","zh":"这个包对我来说太贵了。","scene":"shopping","register":"casual"},{"jp":"一度に説明が多すぎると、理解しにくいです。","zh":"一次说明太多会难以理解。","scene":"workplace","register":"polite"}]},
  {"seed_key":"gp_ext_you_ni_naru","grammar_point":"〜ようになる","canonical_form":"〜ようになる","sense_key":"you_ni_naru_acquired_change","form_group_slug":"you_ni_naru","point_type":"grammar_pattern","primary_node_slug":"change_start_continuation_end","secondary_node_slugs":["progressive_state_experience_completion","ability_potential_difficulty"],"sub_category":"能力与习惯变化","core_meaning":"表示经过变化后变得能做、开始做或不再做某事。","natural_translation":"变得会……／开始……","structure":"V辞书形/ない形 + ようになる","usage_notes":"强调状态变化的结果，不表示说话人当场作出的决定。","practicality":"S","spoken_or_written":"both","jlpt_level":"N4","common_mistakes":["自己的决定用「ことにする」，不能一律用「ようになる」。"],"base_type":"verb","required_form":"辞书形或ない形","scenes":["daily_life","school","workplace"],"registers":["casual","polite","written"],"stage_slug":"functional_patterns","module_slug":"purpose_request_obligation","sort_order":10,"prerequisite_seed_keys":["gp_dict_form","gp_nai_form","gp_ninaru_change"],"examples":[{"jp":"毎日練習して、日本語が話せるようになりました。","zh":"每天练习后，变得会说日语了。","scene":"school","register":"polite"},{"jp":"最近、早く起きるようになった。","zh":"最近开始早起了。","scene":"daily_life","register":"casual"},{"jp":"この設定で通知が表示されないようになります。","zh":"使用这个设置后，通知将不再显示。","scene":"workplace","register":"polite"}]},
  {"seed_key":"gp_ext_koto_ni_naru","grammar_point":"〜ことになる","canonical_form":"〜ことになる","sense_key":"koto_ni_naru_external_decision","form_group_slug":"koto_ni_naru","point_type":"grammar_pattern","primary_node_slug":"change_start_continuation_end","secondary_node_slugs":["purpose_and_plans"],"sub_category":"外部决定与结果","core_meaning":"表示由组织、情况或他人决定的安排，或逻辑上形成的结果。","natural_translation":"决定要……／结果就是……","structure":"V辞书形/ない形 + ことになる","usage_notes":"和个人主动决定的「ことにする」区分。","practicality":"S","spoken_or_written":"both","jlpt_level":"N4","common_mistakes":["自己当场决定做某事时通常用「ことにする」。"],"base_type":"verb","required_form":"辞书形或ない形","scenes":["workplace","school","daily_life"],"registers":["casual","polite","business"],"stage_slug":"functional_patterns","module_slug":"purpose_request_obligation","sort_order":20,"prerequisite_seed_keys":["gp_koto_nominalization","gp_ninaru_change"],"examples":[{"jp":"来月から大阪支社で働くことになりました。","zh":"决定从下个月开始在大阪分公司工作。","scene":"workplace","register":"business"},{"jp":"雨のため、試合は延期することになった。","zh":"因为下雨，比赛决定延期。","scene":"school","register":"casual"},{"jp":"このまま進めると、予定を変更することになります。","zh":"照这样推进的话，结果就要修改计划。","scene":"workplace","register":"polite"}]},
  {"seed_key":"gp_ext_koto_ni_natteiru","grammar_point":"〜ことになっている","canonical_form":"〜ことになっている","sense_key":"koto_ni_natteiru_rule_schedule","form_group_slug":"koto_ni_naru","point_type":"grammar_pattern","primary_node_slug":"obligation_necessity_unnecessity","secondary_node_slugs":["change_start_continuation_end","progressive_state_experience_completion"],"sub_category":"规定与既定安排","core_meaning":"表示已经确定并持续有效的规则、制度或安排。","natural_translation":"规定……／安排为……","structure":"V辞书形/ない形 + ことになっている","usage_notes":"不是个人临时习惯；个人习惯常用「ことにしている」。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["不要用它表达自己随意决定的习惯。"],"base_type":"verb","required_form":"辞书形或ない形","scenes":["workplace","school","government_office"],"registers":["polite","business","formal"],"stage_slug":"functional_patterns","module_slug":"purpose_request_obligation","sort_order":30,"prerequisite_seed_keys":["gp_ext_koto_ni_naru","gp_te_iru_result_state"],"examples":[{"jp":"この会社では、九時までに出社することになっています。","zh":"这家公司规定九点前到岗。","scene":"workplace","register":"business"},{"jp":"図書館では飲食しないことになっています。","zh":"图书馆规定不得饮食。","scene":"school","register":"formal"},{"jp":"面接はオンラインで行うことになっています。","zh":"面试安排在线上进行。","scene":"interview","register":"polite"}]},
  {"seed_key":"gp_ext_koto_ga_dekiru","grammar_point":"〜ことができる","canonical_form":"〜ことができる","sense_key":"koto_ga_dekiru_ability_permission","form_group_slug":"ability_expression","point_type":"grammar_pattern","primary_node_slug":"ability_potential_difficulty","secondary_node_slugs":["modification_connection_nominalization"],"sub_category":"能力与条件允许","core_meaning":"表示具备做某事的能力，或条件、规则允许做某事。","natural_translation":"能够……／可以……","structure":"V辞书形 + ことができる","usage_notes":"比动词可能形更便于接长动作内容，也常用于正式说明。","practicality":"S","spoken_or_written":"both","jlpt_level":"N4","common_mistakes":["前项必须使用辞书形，不能接ます形。"],"base_type":"verb","required_form":"辞书形","scenes":["daily_life","workplace","government_office"],"registers":["casual","polite","formal"],"stage_slug":"functional_patterns","module_slug":"purpose_request_obligation","sort_order":40,"prerequisite_seed_keys":["gp_dict_form","gp_koto_nominalization","gp_dekiru"],"examples":[{"jp":"このアプリで予約を変更することができます。","zh":"可以用这个应用修改预约。","scene":"daily_life","register":"polite"},{"jp":"外国人もオンラインで申請することができます。","zh":"外国人也可以在线申请。","scene":"government_office","register":"formal"},{"jp":"今日は早く帰ることができる。","zh":"今天能早点回去。","scene":"workplace","register":"casual"}]},
  {"seed_key":"gp_ext_ka_douka","grammar_point":"〜かどうか","canonical_form":"〜かどうか","sense_key":"ka_douka_embedded_yes_no","form_group_slug":"ka_douka","point_type":"grammar_pattern","primary_node_slug":"quotation_reporting_topic","secondary_node_slugs":["noun_modifying_clauses"],"sub_category":"嵌入式是否疑问","core_meaning":"把“是否……”作为句中的名词性内容。","natural_translation":"是否……","structure":"普通形 + かどうか","usage_notes":"后接确认、决定、知道、调查等谓语；前项通常不加句末「か」。","practicality":"S","spoken_or_written":"both","jlpt_level":"N4","common_mistakes":["不要说「行きますかどうか」；通常接普通形「行くかどうか」。"],"base_type":"clause","required_form":"普通形","scenes":["daily_life","workplace","school"],"registers":["casual","polite","written"],"stage_slug":"functional_patterns","module_slug":"quotation_information","sort_order":10,"prerequisite_seed_keys":["gp_plain_style","gp_koto_nominalization"],"examples":[{"jp":"参加できるかどうか、明日までに連絡します。","zh":"能否参加，我会在明天前联系。","scene":"workplace","register":"polite"},{"jp":"この答えが正しいかどうか確認してください。","zh":"请确认这个答案是否正确。","scene":"school","register":"polite"},{"jp":"彼が来るかどうか分からない。","zh":"不知道他会不会来。","scene":"friend_chat","register":"casual"}]},
  {"seed_key":"gp_ext_made_ni","grammar_point":"〜までに","canonical_form":"〜までに","sense_key":"made_ni_deadline","form_group_slug":"made","point_type":"grammar_pattern","primary_node_slug":"time_and_sequence","secondary_node_slugs":["comparison_degree_scope"],"sub_category":"完成期限","core_meaning":"表示某动作最晚需要在指定时间点之前完成。","natural_translation":"在……之前／最晚到……","structure":"时间/名词 + までに","usage_notes":"后项是一次性完成事项；持续状态的终点使用「まで」。","practicality":"S","spoken_or_written":"both","jlpt_level":"N4","common_mistakes":["「五時まで働く」和「五時までに提出する」不能互换。"],"base_type":"noun","required_form":"时间名词","scenes":["workplace","school","government_office"],"registers":["casual","polite","business","formal"],"stage_slug":"foundations","module_slug":"reference_quantity","sort_order":40,"prerequisite_seed_keys":["gp_ext_made_limit"],"examples":[{"jp":"資料は金曜日までに提出してください。","zh":"请在周五之前提交资料。","scene":"workplace","register":"business"},{"jp":"宿題を明日までに終わらせます。","zh":"会在明天之前完成作业。","scene":"school","register":"polite"},{"jp":"申請書は今月末までに郵送してください。","zh":"请在本月底前邮寄申请表。","scene":"government_office","register":"formal"}]},
  {"seed_key":"gp_ext_okini_gotoni","grammar_point":"〜おきに／〜ごとに","canonical_form":"〜おきに／〜ごとに","sense_key":"okini_gotoni_interval_frequency","form_group_slug":"frequency_interval","point_type":"grammar_pattern","primary_node_slug":"time_and_sequence","secondary_node_slugs":["comparison_degree_scope"],"sub_category":"间隔与频率","core_meaning":"表示按固定间隔或每个单位重复发生。","natural_translation":"每隔……／每……","structure":"数量 + おきに；数量/名词 + ごとに","usage_notes":"「一日おきに」通常表示隔一天一次；「一日ごとに」表示每天或逐日，需按单位理解。","practicality":"A","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["不要把「一日おき」和「一日ごと」机械翻成相同频率。"],"base_type":"noun","required_form":"数量或名词","scenes":["daily_life","hospital","workplace"],"registers":["casual","polite","written"],"stage_slug":"foundations","module_slug":"reference_quantity","sort_order":50,"prerequisite_seed_keys":["gp_ext_counters_quantity"],"examples":[{"jp":"この薬は六時間おきに飲んでください。","zh":"这种药请每隔六小时服用一次。","scene":"hospital","register":"polite"},{"jp":"一週間ごとに進捗を報告します。","zh":"每周汇报进展。","scene":"workplace","register":"business"},{"jp":"一日おきにジョギングしている。","zh":"隔一天跑一次步。","scene":"daily_life","register":"casual"}]},
  {"seed_key":"gp_ext_demonstrative_system","grammar_point":"こ・そ・あ・ど指示体系","canonical_form":"こ・そ・あ・ど","sense_key":"demonstrative_ko_so_a_do","form_group_slug":"demonstratives","point_type":"syntax_concept","primary_node_slug":"word_order_focus","secondary_node_slugs":["topic_subject_predicate"],"sub_category":"指示与共同注意","core_meaning":"根据说话双方的距离、信息归属和共同认知选择指示词。","natural_translation":"这／那／哪","structure":"これ/それ/あれ/どれ；ここ/そこ/あそこ/どこ；この/その/あの/どの + 名词","usage_notes":"「そ」系列也可指对方刚提到的信息，「あ」系列常指双方都知道的事物。","practicality":"S","spoken_or_written":"both","jlpt_level":"N5","common_mistakes":["不要只按物理距离选择「それ」和「あれ」，还要看信息是否双方共有。"],"base_type":"noun","required_form":"指示词","scenes":["daily_life","shopping","workplace"],"registers":["casual","polite"],"stage_slug":"foundations","module_slug":"reference_quantity","sort_order":60,"prerequisite_seed_keys":["gp_topic_subject_structure"],"examples":[{"jp":"この資料を見てください。","zh":"请看这份资料。","scene":"workplace","register":"polite"},{"jp":"それはどこで買ったの？","zh":"那个是在哪里买的？","scene":"friend_chat","register":"casual"},{"jp":"あの店は前に一緒に行きましたね。","zh":"那家店我们以前一起去过吧。","scene":"daily_life","register":"polite"}]},
  {"seed_key":"gp_ext_counters_quantity","grammar_point":"数量词与助数词","canonical_form":"数量词与助数词","sense_key":"quantity_counter_system","form_group_slug":"quantity_counters","point_type":"syntax_concept","primary_node_slug":"comparison_degree_scope","secondary_node_slugs":["word_order_focus"],"sub_category":"数量与计数单位","core_meaning":"根据所计数对象选择人、枚、本、台、回等助数词，并放入自然语序。","natural_translation":"几个／几人／几本……","structure":"数量 + 助数词；名词を + 数量词 + 谓语","usage_notes":"数量词通常放在相关名词助词之后、谓语之前；特殊读音需要连同助数词记忆。","practicality":"S","spoken_or_written":"both","jlpt_level":"N5","common_mistakes":["不要把中文量词直接替换；日语助数词及音变需要按对象选择。"],"base_type":"noun","required_form":"数量与助数词","scenes":["shopping","restaurant","daily_life"],"registers":["casual","polite"],"stage_slug":"foundations","module_slug":"reference_quantity","sort_order":70,"prerequisite_seed_keys":["gp_wo","gp_word_order_focus"],"examples":[{"jp":"りんごを三つ買いました。","zh":"买了三个苹果。","scene":"shopping","register":"polite"},{"jp":"会議には十人参加します。","zh":"有十个人参加会议。","scene":"workplace","register":"polite"},{"jp":"この薬を一日二回飲んでください。","zh":"这种药请一天服用两次。","scene":"hospital","register":"polite"}]}
