[
  {"seed_key":"gp_ext_o_go_ninaru","grammar_point":"お／ご〜になる","canonical_form":"お／ご〜になる","sense_key":"honorific_o_go_ninaru","form_group_slug":"productive_honorifics","point_type":"grammar_pattern","primary_node_slug":"honorifics_and_politeness","secondary_node_slugs":["honorific_humble_language","verb_conjugation_basics"],"sub_category":"生产性尊敬语","core_meaning":"用固定构式抬高对方或第三者的动作。","natural_translation":"您……／某位……","structure":"お + Vます去ます + になる；ご + 汉语词干 + になる","usage_notes":"和语动词多用「お」，汉语词多用「ご」；部分已有特殊尊敬动词时优先使用词汇形式。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["不要用于自己的动作，也不要和特殊尊敬动词重复敬语化。"],"base_type":"verb","required_form":"ます形去ます或汉语词干","scenes":["workplace","customer_service","interview"],"registers":["business","formal","customer"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":10,"prerequisite_seed_keys":["gp_masu_form","gp_honorific_language"],"examples":[{"jp":"部長はもうお帰りになりました。","zh":"部长已经回去了。","scene":"workplace","register":"business"},{"jp":"こちらの資料をご覧になりますか。","zh":"您要看这份资料吗？","scene":"customer_service","register":"customer"},{"jp":"先生は何時にお着きになりますか。","zh":"老师几点到？","scene":"school","register":"formal"}]},
  {"seed_key":"gp_ext_o_go_suru","grammar_point":"お／ご〜する","canonical_form":"お／ご〜する","sense_key":"humble_o_go_suru","form_group_slug":"productive_honorifics","point_type":"grammar_pattern","primary_node_slug":"honorifics_and_politeness","secondary_node_slugs":["honorific_humble_language","verb_conjugation_basics"],"sub_category":"生产性谦让语","core_meaning":"用固定构式降低自己或己方动作，向动作对象表示敬意。","natural_translation":"我来为您……","structure":"お + Vます去ます + する；ご + 汉语词干 + する","usage_notes":"动作通常指向需要尊敬的对象；没有敬意对象的纯个人动作不使用。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["不能把没有对方受益或指向的动作都改成「お／ご〜する」。"],"base_type":"verb","required_form":"ます形去ます或汉语词干","scenes":["workplace","customer_service","email"],"registers":["business","customer","formal"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":20,"prerequisite_seed_keys":["gp_masu_form","gp_humble_language"],"examples":[{"jp":"私が会議室までご案内します。","zh":"我带您到会议室。","scene":"workplace","register":"business"},{"jp":"後ほど資料をお送りします。","zh":"稍后我会给您发送资料。","scene":"email","register":"business"},{"jp":"お荷物をお持ちしましょうか。","zh":"我来帮您拿行李吧？","scene":"customer_service","register":"customer"}]},
  {"seed_key":"gp_ext_o_go_itadaku","grammar_point":"お／ご〜いただく","canonical_form":"お／ご〜いただく","sense_key":"benefactive_o_go_itadaku","form_group_slug":"productive_honorifics","point_type":"grammar_pattern","primary_node_slug":"honorifics_and_politeness","secondary_node_slugs":["honorific_humble_language","giving_receiving_benefit"],"sub_category":"郑重受益","core_meaning":"郑重表示承蒙对方进行某动作。","natural_translation":"承蒙您……","structure":"お + Vます去ます + いただく；ご + 汉语词干 + いただく","usage_notes":"可用于感谢、说明已获协助，也可和可能／请求形式组合。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["对方并未为己方做事时不要机械使用「いただく」。"],"base_type":"verb","required_form":"ます形去ます或汉语词干","scenes":["workplace","email","customer_service"],"registers":["business","formal","customer"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":30,"prerequisite_seed_keys":["gp_te_itadaku","gp_humble_language"],"examples":[{"jp":"本日はお越しいただき、ありがとうございます。","zh":"感谢您今天莅临。","scene":"workplace","register":"business"},{"jp":"内容をご確認いただきました。","zh":"承蒙您确认了内容。","scene":"email","register":"business"},{"jp":"多くのお客様にご利用いただいております。","zh":"承蒙众多顾客使用。","scene":"customer_service","register":"customer"}]},
  {"seed_key":"gp_ext_te_kudasaru","grammar_point":"〜てくださる","canonical_form":"〜てくださる","sense_key":"te_kudasaru_honorific_benefit","form_group_slug":"giving_receiving","point_type":"grammar_pattern","primary_node_slug":"giving_receiving_benefit","secondary_node_slugs":["honorifics_and_politeness","honorific_humble_language"],"sub_category":"尊敬授受","core_meaning":"尊敬地表示对方主动为我方做某事。","natural_translation":"您特意为我……","structure":"Vて形 + くださる","usage_notes":"视角与「〜てくれる」相同，但抬高动作主体；礼貌形为「くださいます」。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["若强调我方请求并获得帮助，应考虑「〜ていただく」。"],"base_type":"verb","required_form":"て形","scenes":["workplace","school","hospital"],"registers":["polite","business","formal"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":40,"prerequisite_seed_keys":["gp_te_form","gp_te_kureru","gp_honorific_language"],"examples":[{"jp":"先生が推薦状を書いてくださいました。","zh":"老师为我写了推荐信。","scene":"school","register":"formal"},{"jp":"部長が直接説明してくださいました。","zh":"部长亲自为我们说明了。","scene":"workplace","register":"business"},{"jp":"医師が検査結果を詳しく教えてくださいました。","zh":"医生详细告诉了我检查结果。","scene":"hospital","register":"polite"}]},
  {"seed_key":"gp_ext_te_itadakenai_deshouka","grammar_point":"〜ていただけないでしょうか","canonical_form":"〜ていただけないでしょうか","sense_key":"request_te_itadakenai_deshouka","form_group_slug":"polite_requests","point_type":"grammar_pattern","primary_node_slug":"requests_permission_advice","secondary_node_slugs":["honorifics_and_politeness","giving_receiving_benefit"],"sub_category":"委婉郑重请求","core_meaning":"通过否定可能疑问郑重、委婉地请求对方。","natural_translation":"能否请您……","structure":"Vて形 + いただけないでしょうか","usage_notes":"比「〜ていただけますか」更委婉，适合上级、客户和正式邮件。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["日常简单请求中过度使用会显得距离过远。"],"base_type":"verb","required_form":"て形","scenes":["workplace","email","hospital"],"registers":["business","formal","soft"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":50,"prerequisite_seed_keys":["gp_te_form","gp_te_itadakemasu_ka"],"examples":[{"jp":"資料を明日までにお送りいただけないでしょうか。","zh":"能否请您在明天前发送资料？","scene":"email","register":"business"},{"jp":"もう少しゆっくり説明していただけないでしょうか。","zh":"能否请您再讲慢一点？","scene":"hospital","register":"formal"},{"jp":"日程を再調整していただけないでしょうか。","zh":"能否请您重新协调一下日程？","scene":"workplace","register":"business"}]},
  {"seed_key":"gp_ext_te_itadakereba_saiwai","grammar_point":"〜ていただければ幸いです","canonical_form":"〜ていただければ幸いです","sense_key":"request_te_itadakereba_saiwai","form_group_slug":"polite_requests","point_type":"grammar_pattern","primary_node_slug":"requests_permission_advice","secondary_node_slugs":["honorifics_and_politeness","formulaic_scene_expressions"],"sub_category":"书面郑重请求","core_meaning":"在邮件或正式书面语中委婉表达希望对方配合。","natural_translation":"如蒙……将不胜感激","structure":"Vて形 + いただければ幸いです","usage_notes":"是明确请求而非单纯表达幸运；紧急口头指令不适合。","practicality":"S","spoken_or_written":"written","jlpt_level":"N3","common_mistakes":["不要在需要立即明确行动的紧急场景中用得过于委婉。"],"base_type":"verb","required_form":"て形","scenes":["email","workplace","government_office"],"registers":["business","formal","written"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":60,"prerequisite_seed_keys":["gp_te_itadaku","gp_ba"],"examples":[{"jp":"添付資料をご確認いただければ幸いです。","zh":"如能确认附件资料，将不胜感激。","scene":"email","register":"business"},{"jp":"今週中にご回答いただければ幸いです。","zh":"如能在本周内答复，将非常感谢。","scene":"workplace","register":"formal"},{"jp":"申請内容をご確認いただければ幸いです。","zh":"烦请确认申请内容。","scene":"government_office","register":"written"}]},
  {"seed_key":"gp_ext_sasete_itadakereba_to_omou","grammar_point":"〜させていただければと思います","canonical_form":"〜させていただければと思います","sense_key":"proposal_sasete_itadakereba_to_omou","form_group_slug":"sasete_itadaku","point_type":"grammar_pattern","primary_node_slug":"honorifics_and_politeness","secondary_node_slugs":["giving_receiving_benefit","purpose_and_plans"],"sub_category":"委婉提出己方行动","core_meaning":"委婉说明希望在对方许可下采取某项行动。","natural_translation":"希望允许我们……","structure":"V使役て形 + いただければと思います","usage_notes":"应存在需要对方许可或受对方影响的行动；不能作为任何商务动作的万能包装。","practicality":"A","spoken_or_written":"both","jlpt_level":"N2","common_mistakes":["没有许可关系时滥用「させていただく」会显得冗长不自然。"],"base_type":"verb","required_form":"使役て形","scenes":["workplace","email","interview"],"registers":["business","formal"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":70,"prerequisite_seed_keys":["gp_causative_form","gp_sasete_itadakimasu"],"examples":[{"jp":"本日は新しい案をご説明させていただければと思います。","zh":"今天希望允许我说明新方案。","scene":"workplace","register":"business"},{"jp":"詳細は改めてご連絡させていただければと思います。","zh":"详细情况希望容后再联系您。","scene":"email","register":"business"},{"jp":"まず自己紹介をさせていただければと思います。","zh":"首先请允许我做自我介绍。","scene":"interview","register":"formal"}]},
  {"seed_key":"gp_ext_de_irassharu","grammar_point":"〜でいらっしゃる","canonical_form":"〜でいらっしゃる","sense_key":"copula_de_irassharu","form_group_slug":"honorific_copula","point_type":"grammar_pattern","primary_node_slug":"honorifics_and_politeness","secondary_node_slugs":["honorific_humble_language","basic_sentence_patterns"],"sub_category":"尊敬判断句","core_meaning":"尊敬地表达对方的身份或状态，相当于「です／である」。","natural_translation":"您是……／处于……","structure":"名词/な形容词 + でいらっしゃる","usage_notes":"用于抬高主语；客服确认身份时常见。","practicality":"A","spoken_or_written":"both","jlpt_level":"N2","common_mistakes":["不能用于降低自己，自己的身份用「でございます」等形式。"],"base_type":"noun","required_form":"名词或な形容词词干","scenes":["customer_service","workplace","interview"],"registers":["customer","business","formal"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":80,"prerequisite_seed_keys":["gp_de_gozaimasu","gp_honorific_language"],"examples":[{"jp":"田中様でいらっしゃいますか。","zh":"请问您是田中先生／女士吗？","scene":"customer_service","register":"customer"},{"jp":"先生はご専門が言語学でいらっしゃいます。","zh":"老师的专业是语言学。","scene":"school","register":"formal"},{"jp":"こちらが新しいご担当者でいらっしゃいます。","zh":"这位就是新的负责人。","scene":"workplace","register":"business"}]},
  {"seed_key":"gp_ext_to_mousu","grammar_point":"〜と申します","canonical_form":"〜と申します","sense_key":"humble_to_mousu_name","form_group_slug":"mousu","point_type":"grammar_pattern","primary_node_slug":"honorifics_and_politeness","secondary_node_slugs":["honorific_humble_language","quotation_reporting_topic"],"sub_category":"谦让自我介绍","core_meaning":"谦让地介绍自己的姓名或称呼。","natural_translation":"我叫……","structure":"姓名/名称 + と申します","usage_notes":"首次商务联系、自我介绍和电话开场中高频。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["介绍对方姓名不能用降低自己的「申します」。"],"base_type":"noun","required_form":"姓名或名称","scenes":["workplace","phone_call","interview"],"registers":["business","formal"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":90,"prerequisite_seed_keys":["gp_to_iu","gp_humble_language"],"examples":[{"jp":"ABC商事の王と申します。","zh":"我是ABC商事的王。","scene":"phone_call","register":"business"},{"jp":"本日面接を受ける李と申します。","zh":"我是今天来参加面试的李。","scene":"interview","register":"formal"},{"jp":"初めまして、山田と申します。","zh":"初次见面，我叫山田。","scene":"workplace","register":"business"}]},
  {"seed_key":"gp_ext_to_zonjiru","grammar_point":"〜と存じます","canonical_form":"〜と存じます","sense_key":"humble_to_zonjiru_opinion","form_group_slug":"zonjiru","point_type":"grammar_pattern","primary_node_slug":"honorifics_and_politeness","secondary_node_slugs":["honorific_humble_language","inference_judgment_sources"],"sub_category":"谦让判断","core_meaning":"郑重、谦让地表达自己的想法或判断，相当于「と思います」。","natural_translation":"我认为……／想必……","structure":"普通形 + と存じます","usage_notes":"常用于邮件、致辞和郑重说明；日常对话使用会显得过度正式。","practicality":"A","spoken_or_written":"both","jlpt_level":"N2","common_mistakes":["不要把对方的想法说成「存じます」；那是己方的谦让表达。"],"base_type":"clause","required_form":"普通形","scenes":["email","workplace","customer_service"],"registers":["business","formal","written"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":100,"prerequisite_seed_keys":["gp_to_omou","gp_humble_language"],"examples":[{"jp":"ご多忙のことと存じます。","zh":"想必您事务繁忙。","scene":"email","register":"business"},{"jp":"この方法が最適かと存じます。","zh":"我认为这个方法最合适。","scene":"workplace","register":"formal"},{"jp":"近日中に回答できるものと存じます。","zh":"我想近日内可以答复。","scene":"customer_service","register":"business"}]},
  {"seed_key":"gp_ext_te_mairu","grammar_point":"〜てまいります","canonical_form":"〜てまいります","sense_key":"humble_te_mairu_continuation","form_group_slug":"te_kuru_iku","point_type":"grammar_pattern","primary_node_slug":"honorifics_and_politeness","secondary_node_slugs":["honorific_humble_language","change_start_continuation_end"],"sub_category":"谦让的持续行动","core_meaning":"郑重表示己方过去持续到现在或今后继续进行某事。","natural_translation":"一直……／今后将继续……","structure":"Vて形 + まいります","usage_notes":"是「〜てくる／〜ていく」的谦让郑重形式，商务说明和承诺中常见。","practicality":"A","spoken_or_written":"both","jlpt_level":"N2","common_mistakes":["不要把所有移动都解释成持续变化；也可能是「行ってくる」的谦让形式。"],"base_type":"verb","required_form":"て形","scenes":["workplace","email","customer_service"],"registers":["business","formal","customer"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":110,"prerequisite_seed_keys":["gp_te_form","gp_te_kuru","gp_humble_language"],"examples":[{"jp":"今後も品質向上に努めてまいります。","zh":"今后也将继续努力提高质量。","scene":"customer_service","register":"customer"},{"jp":"これまで地域の皆様と協力してまいりました。","zh":"至今一直与当地各位合作。","scene":"workplace","register":"formal"},{"jp":"資料を取ってまいりますので、少々お待ちください。","zh":"我去取资料，请稍等。","scene":"workplace","register":"business"}]},
  {"seed_key":"gp_ext_irregular_sonkeigo","grammar_point":"常用尊敬语动词","canonical_form":"常用尊敬语动词","sense_key":"lexical_irregular_sonkeigo","form_group_slug":"lexical_honorifics","point_type":"register_concept","primary_node_slug":"honorific_humble_language","secondary_node_slugs":["honorifics_and_politeness"],"sub_category":"词汇型尊敬语","core_meaning":"用专门词汇抬高对方的来、在、吃、看、说、做等动作。","natural_translation":"いらっしゃる／召し上がる／ご覧になる／おっしゃる／なさる","structure":"行く・来る・いる→いらっしゃる；食べる・飲む→召し上がる；見る→ご覧になる；言う→おっしゃる；する→なさる","usage_notes":"特殊词汇通常比生产性「お／ご〜になる」更自然。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["不要说「おっしゃられる」等二重敬语。"],"base_type":"verb","required_form":"对应普通动词","scenes":["workplace","customer_service","school"],"registers":["business","formal","customer"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":120,"prerequisite_seed_keys":["gp_honorific_language"],"examples":[{"jp":"社長は午後こちらにいらっしゃいます。","zh":"社长下午会来这里。","scene":"workplace","register":"business"},{"jp":"どうぞ温かいうちに召し上がってください。","zh":"请趁热享用。","scene":"customer_service","register":"customer"},{"jp":"先生がおっしゃった内容を確認しました。","zh":"确认了老师所说的内容。","scene":"school","register":"formal"}]},
  {"seed_key":"gp_ext_irregular_kenjougo","grammar_point":"常用谦让语动词","canonical_form":"常用谦让语动词","sense_key":"lexical_irregular_kenjougo","form_group_slug":"lexical_honorifics","point_type":"register_concept","primary_node_slug":"honorific_humble_language","secondary_node_slugs":["honorifics_and_politeness"],"sub_category":"词汇型谦让语","core_meaning":"用专门词汇降低己方的去、来、说、看、听、知道等动作。","natural_translation":"伺う／参る／申す／申し上げる／拝見する／承る／存じる","structure":"行く・来る・聞く→伺う；行く・来る→参る；言う→申す/申し上げる；見る→拝見する；聞く・受ける→承る；知る→存じる","usage_notes":"根据动作对象和固定搭配选择词汇；并非一一机械替换。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["不要用谦让语描述客户或上级的动作。"],"base_type":"verb","required_form":"对应普通动词","scenes":["workplace","phone_call","email"],"registers":["business","formal"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":130,"prerequisite_seed_keys":["gp_humble_language"],"examples":[{"jp":"明日の午後、御社へ伺います。","zh":"明天下午去贵公司拜访。","scene":"workplace","register":"business"},{"jp":"送っていただいた資料を拝見しました。","zh":"拜读了您发送的资料。","scene":"email","register":"business"},{"jp":"ご注文を承りました。","zh":"已受理您的订单。","scene":"phone_call","register":"formal"}]},
  {"seed_key":"gp_ext_ni_tsukimashite","grammar_point":"〜につきまして","canonical_form":"〜につきまして","sense_key":"ni_tsukimashite_formal_topic","form_group_slug":"ni_tsuite","point_type":"grammar_pattern","primary_node_slug":"quotation_reporting_topic","secondary_node_slugs":["compound_particles","honorifics_and_politeness"],"sub_category":"正式话题提示","core_meaning":"郑重提出接下来说明、询问或联系的主题。","natural_translation":"关于……","structure":"名词 + につきまして","usage_notes":"是「について」的郑重商务形式，适合邮件、会议和客服。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["日常朋友会话中使用会显得过度正式。"],"base_type":"noun","required_form":"名词","scenes":["email","workplace","customer_service"],"registers":["business","formal","customer"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":140,"prerequisite_seed_keys":["gp_ni_tsuite","gp_polite_style"],"examples":[{"jp":"ご契約内容につきまして、ご説明いたします。","zh":"关于合同内容，为您作说明。","scene":"customer_service","register":"customer"},{"jp":"来週の会議につきまして、ご連絡いたします。","zh":"现就下周会议与您联系。","scene":"email","register":"business"},{"jp":"この件につきまして、ご意見をいただけますか。","zh":"关于此事，能请您提供意见吗？","scene":"workplace","register":"formal"}]},
  {"seed_key":"gp_ext_ni_kanshimashite","grammar_point":"〜に関しまして","canonical_form":"〜に関しまして","sense_key":"ni_kanshimashite_formal_regarding","form_group_slug":"ni_kansuru","point_type":"grammar_pattern","primary_node_slug":"quotation_reporting_topic","secondary_node_slugs":["compound_particles","honorifics_and_politeness"],"sub_category":"正式相关说明","core_meaning":"郑重表示后文内容与某主题相关。","natural_translation":"有关……／关于……","structure":"名词 + に関しまして","usage_notes":"比「につきまして」略偏书面说明；两者在很多商务场景可互换。","practicality":"A","spoken_or_written":"both","jlpt_level":"N2","common_mistakes":["不要与表示对象态度的「に対して」混淆。"],"base_type":"noun","required_form":"名词","scenes":["email","workplace","government_office"],"registers":["business","formal","written"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":150,"prerequisite_seed_keys":["gp_ni_tsuite","gp_polite_style"],"examples":[{"jp":"個人情報の取り扱いに関しまして、以下をご確認ください。","zh":"关于个人信息处理，请确认以下内容。","scene":"email","register":"written"},{"jp":"新制度に関しまして、ご質問はありますか。","zh":"关于新制度，您有问题吗？","scene":"workplace","register":"business"},{"jp":"申請手続きに関しまして、窓口でご案内します。","zh":"有关申请手续，将在窗口为您说明。","scene":"government_office","register":"formal"}]},
  {"seed_key":"gp_ext_ni_atari","grammar_point":"〜にあたり","canonical_form":"〜にあたり","sense_key":"ni_atari_important_occasion","form_group_slug":"occasion_formal","point_type":"grammar_pattern","primary_node_slug":"time_and_sequence","secondary_node_slugs":["compound_particles","formal"],"sub_category":"重要时机","core_meaning":"表示在开始重要行动或迎来重要场合之际。","natural_translation":"在……之际","structure":"V辞书形/名词 + にあたり","usage_notes":"用于具有准备、责任或正式意义的场合，不用于普通日常小事。","practicality":"A","spoken_or_written":"written","jlpt_level":"N2","common_mistakes":["不要说「昼ご飯を食べるにあたり」等过于日常的事项。"],"base_type":"clause","required_form":"辞书形或名词","scenes":["workplace","interview","government_office"],"registers":["formal","business","written"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":160,"prerequisite_seed_keys":["gp_dict_form","gp_toki"],"examples":[{"jp":"新事業を始めるにあたり、方針を確認します。","zh":"在开始新业务之际，确认方针。","scene":"workplace","register":"formal"},{"jp":"入社にあたり、必要書類を提出してください。","zh":"入职之际，请提交必要材料。","scene":"workplace","register":"business"},{"jp":"面接にあたり、本人確認を行います。","zh":"面试之际，将进行身份确认。","scene":"interview","register":"formal"}]},
  {"seed_key":"gp_ext_ni_saishite","grammar_point":"〜に際して","canonical_form":"〜に際して","sense_key":"ni_saishite_formal_occasion","form_group_slug":"occasion_formal","point_type":"grammar_pattern","primary_node_slug":"time_and_sequence","secondary_node_slugs":["compound_particles","formal"],"sub_category":"正式时机","core_meaning":"在某个特殊事件或正式行动发生时，说明相关准备或注意事项。","natural_translation":"值……之际／在……时","structure":"V辞书形/名词 + に際して","usage_notes":"和「にあたり」接近，但更强调事件发生时点及对应措施。","practicality":"A","spoken_or_written":"written","jlpt_level":"N2","common_mistakes":["普通反复发生的时间条件通常不用「に際して」。"],"base_type":"clause","required_form":"辞书形或名词","scenes":["workplace","travel","government_office"],"registers":["formal","written"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":170,"prerequisite_seed_keys":["gp_ext_ni_atari"],"examples":[{"jp":"サービスの利用に際して、規約をご確認ください。","zh":"使用服务时，请确认条款。","scene":"customer_service","register":"formal"},{"jp":"海外赴任に際して、研修を受けました。","zh":"海外赴任之际，接受了培训。","scene":"workplace","register":"written"},{"jp":"出国に際して、必要な手続きを行ってください。","zh":"出境时，请办理必要手续。","scene":"travel","register":"formal"}]},
  {"seed_key":"gp_ext_shidai_as_soon","grammar_point":"〜次第（完成后立即）","canonical_form":"〜次第","sense_key":"shidai_as_soon_as","form_group_slug":"shidai","point_type":"grammar_pattern","primary_node_slug":"time_and_sequence","secondary_node_slugs":["formal","purpose_and_plans"],"sub_category":"完成后立即","core_meaning":"表示前项一完成，马上进行预定的后项。","natural_translation":"一……就立即……","structure":"Vます去ます + 次第","usage_notes":"常用于商务承诺和正式安排；后项多是说话人可控制的行动。","practicality":"S","spoken_or_written":"both","jlpt_level":"N2","common_mistakes":["不能直接接辞书形；应使用ます词干。"],"base_type":"verb","required_form":"ます形去ます","scenes":["workplace","email","customer_service"],"registers":["business","formal","written"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":180,"prerequisite_seed_keys":["gp_masu_form","gp_te_kara"],"examples":[{"jp":"準備が整い次第、ご連絡します。","zh":"准备就绪后立即联系您。","scene":"workplace","register":"business"},{"jp":"確認でき次第、改めてご回答いたします。","zh":"确认后立即再次答复您。","scene":"email","register":"formal"},{"jp":"商品が入荷し次第、発送いたします。","zh":"商品到货后立即发货。","scene":"customer_service","register":"customer"}]},
  {"seed_key":"gp_ext_shidai_de","grammar_point":"〜次第で","canonical_form":"〜次第で","sense_key":"shidai_de_depends_on","form_group_slug":"shidai","point_type":"grammar_pattern","primary_node_slug":"conditions_and_hypotheses","secondary_node_slugs":["comparison_degree_scope"],"sub_category":"取决于","core_meaning":"表示结果会随着某个条件、判断或做法而改变。","natural_translation":"取决于……","structure":"名词 + 次第で／次第だ","usage_notes":"本条的「次第」是“情况、安排、取决于”，不表示完成后立即。","practicality":"A","spoken_or_written":"both","jlpt_level":"N2","common_mistakes":["不要把「連絡し次第」和「天気次第で」使用同一接续。"],"base_type":"noun","required_form":"名词","scenes":["workplace","travel","daily_life"],"registers":["polite","business","written"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":190,"prerequisite_seed_keys":["gp_baai","gp_ext_shidai_as_soon"],"examples":[{"jp":"結果は準備次第で大きく変わります。","zh":"结果会因准备情况而大幅变化。","scene":"workplace","register":"business"},{"jp":"天気次第で予定を変更します。","zh":"会根据天气调整计划。","scene":"travel","register":"polite"},{"jp":"使い方次第では、とても便利です。","zh":"根据使用方法，也可以非常方便。","scene":"daily_life","register":"written"}]},
