  {"seed_key":"gp_ext_business_acknowledgement","grammar_point":"承知しました／かしこまりました","canonical_form":"承知しました／かしこまりました","sense_key":"business_acknowledgement","form_group_slug":"business_responses","point_type":"collocation","primary_node_slug":"formulaic_scene_expressions","secondary_node_slugs":["honorifics_and_politeness","honorific_humble_language"],"sub_category":"正式接受与确认","core_meaning":"礼貌确认已理解或接受对方的要求。","natural_translation":"明白了／遵命","structure":"承知しました；かしこまりました","usage_notes":"「かしこまりました」更偏客服和执行指示；「承知しました」适合一般商务确认。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["面对客户或上级避免只说「了解しました」。"],"base_type":"clause","required_form":"固定表达","scenes":["workplace","customer_service","phone_call"],"registers":["business","customer","formal"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":250,"prerequisite_seed_keys":["gp_polite_style","gp_humble_language"],"examples":[{"jp":"承知しました。明日までに対応します。","zh":"明白了，会在明天前处理。","scene":"workplace","register":"business"},{"jp":"かしこまりました。少々お待ちください。","zh":"好的，请稍等。","scene":"customer_service","register":"customer"},{"jp":"ご予約の変更ですね。承知いたしました。","zh":"是要更改预约吧，明白了。","scene":"phone_call","register":"formal"}]},
  {"seed_key":"gp_ext_business_softeners","grammar_point":"恐れ入りますが／お手数ですが","canonical_form":"恐れ入りますが／お手数ですが","sense_key":"business_request_softeners","form_group_slug":"business_softeners","point_type":"collocation","primary_node_slug":"formulaic_scene_expressions","secondary_node_slugs":["honorifics_and_politeness","sentence_final_nuance"],"sub_category":"请求前置缓和","core_meaning":"在提出会给对方带来负担的请求前先表达歉意和顾虑。","natural_translation":"不好意思／劳驾","structure":"恐れ入りますが、请求；お手数ですが、请求","usage_notes":"「お手数ですが」强调给对方添麻烦；「恐れ入りますが」也可用于打扰、询问。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["使用缓和语后仍需给出清楚具体的请求。"],"base_type":"clause","required_form":"固定前置表达","scenes":["workplace","email","customer_service"],"registers":["business","formal","customer","soft"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":260,"prerequisite_seed_keys":["gp_ndesuga","gp_polite_style"],"examples":[{"jp":"恐れ入りますが、お名前をもう一度お願いします。","zh":"不好意思，请再说一次您的姓名。","scene":"phone_call","register":"customer"},{"jp":"お手数ですが、資料をご確認ください。","zh":"麻烦您确认资料。","scene":"email","register":"business"},{"jp":"恐れ入りますが、こちらにご記入いただけますか。","zh":"不好意思，能请您填写这里吗？","scene":"customer_service","register":"formal"}]},
  {"seed_key":"gp_ext_business_document_requests","grammar_point":"ご確認／ご査収／ご検討ください","canonical_form":"ご〜ください","sense_key":"business_document_requests","form_group_slug":"business_requests","point_type":"collocation","primary_node_slug":"formulaic_scene_expressions","secondary_node_slugs":["requests_permission_advice","honorifics_and_politeness"],"sub_category":"资料处理请求","core_meaning":"根据资料处理目的，请对方确认、查收或考虑。","natural_translation":"请确认／请查收／请考虑","structure":"ご + 汉语词干 + ください","usage_notes":"「ご査収」用于请对方查收附件或物品；没有发送内容时不能使用。","practicality":"S","spoken_or_written":"written","jlpt_level":"N3","common_mistakes":["不要把「ご査収ください」用于只需阅读而没有附件的邮件。"],"base_type":"noun","required_form":"汉语词干","scenes":["email","workplace","customer_service"],"registers":["business","formal","written"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":270,"prerequisite_seed_keys":["gp_te_kudasai","gp_honorific_language"],"examples":[{"jp":"添付ファイルをご確認ください。","zh":"请确认附件。","scene":"email","register":"business"},{"jp":"見積書をお送りしますので、ご査収ください。","zh":"现发送报价单，请查收。","scene":"email","register":"written"},{"jp":"下記の案についてご検討ください。","zh":"请考虑以下方案。","scene":"workplace","register":"formal"}]},
  {"seed_key":"gp_ext_business_closing","grammar_point":"何卒よろしくお願い申し上げます","canonical_form":"何卒よろしくお願い申し上げます","sense_key":"business_formal_closing","form_group_slug":"business_closing","point_type":"collocation","primary_node_slug":"formulaic_scene_expressions","secondary_node_slugs":["honorifics_and_politeness"],"sub_category":"正式邮件结尾","core_meaning":"在郑重请求、通知或邮件结尾表达恳请和合作期待。","natural_translation":"恳请关照／敬请配合","structure":"何卒 + よろしく + お願い申し上げます","usage_notes":"非常正式；普通日常邮件使用「よろしくお願いします」即可。","practicality":"A","spoken_or_written":"written","jlpt_level":"N2","common_mistakes":["不要在朋友消息中使用，语体距离会非常不自然。"],"base_type":"clause","required_form":"固定表达","scenes":["email","workplace","government_office"],"registers":["business","formal","written"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":280,"prerequisite_seed_keys":["gp_onegai_itashimasu","gp_humble_language"],"examples":[{"jp":"ご理解のほど、何卒よろしくお願い申し上げます。","zh":"恳请理解与配合。","scene":"email","register":"formal"},{"jp":"今後とも何卒よろしくお願い申し上げます。","zh":"今后也恳请继续关照。","scene":"workplace","register":"business"},{"jp":"期限内のご提出を何卒よろしくお願い申し上げます。","zh":"恳请在期限内提交。","scene":"government_office","register":"written"}]},
  {"seed_key":"gp_ext_omatase_itashimashita","grammar_point":"お待たせいたしました","canonical_form":"お待たせいたしました","sense_key":"service_omatase_itashimashita","form_group_slug":"service_apologies","point_type":"collocation","primary_node_slug":"formulaic_scene_expressions","secondary_node_slugs":["honorifics_and_politeness","collocations_and_idioms"],"sub_category":"等待致歉","core_meaning":"服务方在让对方等待后郑重致歉并重新开始沟通。","natural_translation":"让您久等了","structure":"お待たせいたしました","usage_notes":"即使等待时间不长，服务场景恢复沟通时也可使用。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N3","common_mistakes":["不是告别语，应在结束等待、开始处理时使用。"],"base_type":"clause","required_form":"固定表达","scenes":["customer_service","restaurant","phone_call"],"registers":["customer","business","formal"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":290,"prerequisite_seed_keys":["gp_humble_language"],"examples":[{"jp":"お待たせいたしました。こちらがご注文の商品です。","zh":"让您久等了，这是您订购的商品。","scene":"customer_service","register":"customer"},{"jp":"大変お待たせいたしました。お席へご案内します。","zh":"让您久等了，现在带您入座。","scene":"restaurant","register":"customer"},{"jp":"お待たせいたしました。担当者に代わります。","zh":"让您久等了，现在转接负责人。","scene":"phone_call","register":"business"}]},
  {"seed_key":"gp_ext_moushiwake_gozaimasen","grammar_point":"申し訳ございません","canonical_form":"申し訳ございません","sense_key":"formal_apology_moushiwake_gozaimasen","form_group_slug":"service_apologies","point_type":"collocation","primary_node_slug":"formulaic_scene_expressions","secondary_node_slugs":["honorifics_and_politeness","collocations_and_idioms"],"sub_category":"郑重道歉","core_meaning":"对己方造成的不便、错误或无法满足要求表示郑重歉意。","natural_translation":"非常抱歉","structure":"申し訳ございません","usage_notes":"比「すみません」郑重；需要时应继续说明原因、措施或替代方案。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["只说歉语而不给解决方案，服务沟通仍不完整。"],"base_type":"clause","required_form":"固定表达","scenes":["customer_service","workplace","email"],"registers":["customer","business","formal","written"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":300,"prerequisite_seed_keys":["gp_de_gozaimasu","gp_humble_language"],"examples":[{"jp":"ご希望の商品は在庫切れです。申し訳ございません。","zh":"您想要的商品缺货了，非常抱歉。","scene":"customer_service","register":"customer"},{"jp":"返信が遅くなり、申し訳ございません。","zh":"回复晚了，非常抱歉。","scene":"email","register":"business"},{"jp":"こちらの確認不足で、誠に申し訳ございません。","zh":"因我方确认不足，实在非常抱歉。","scene":"workplace","register":"formal"}]}
]
