[
  {"seed_key":"gp_ext_teru_contraction","grammar_point":"〜てる","canonical_form":"〜ている","sense_key":"teiru_casual_contraction_teru","form_group_slug":"te_iru","point_type":"conjugation","primary_node_slug":"casual_spoken_register","secondary_node_slugs":["progressive_state_experience_completion"],"sub_category":"进行体缩约","core_meaning":"在随便口语中把「〜ている」缩约为「〜てる」。","natural_translation":"正在……／一直……","structure":"Vている → Vてる；Vでいる → Vでる","usage_notes":"意义继承原来的进行、状态或习惯；正式和一般礼貌表达保留「いる／います」。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N4","common_mistakes":["不要在正式邮件中使用「〜てる」。"],"base_type":"verb","required_form":"ている形","scenes":["friend_chat","family","online_chat"],"registers":["casual"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":40,"prerequisite_seed_keys":["gp_te_iru","gp_casual_spoken"],"examples":[{"jp":"今、何してる？","zh":"现在在做什么？","scene":"online_chat","register":"casual"},{"jp":"駅の前で待ってるよ。","zh":"我在车站前等你哦。","scene":"friend_chat","register":"casual"},{"jp":"姉は東京に住んでる。","zh":"姐姐住在东京。","scene":"family","register":"casual"}]},
  {"seed_key":"gp_ext_chau_jau","grammar_point":"〜ちゃう／〜じゃう","canonical_form":"〜てしまう","sense_key":"teshimau_casual_contraction","form_group_slug":"te_shimau","point_type":"conjugation","primary_node_slug":"casual_spoken_register","secondary_node_slugs":["progressive_state_experience_completion","sentence_final_nuance"],"sub_category":"完成与遗憾缩约","core_meaning":"在随便口语中缩约「〜てしまう」，表达完成、意外或遗憾。","natural_translation":"……掉了／不小心……","structure":"Vてしまう→Vちゃう；Vでしまう→Vじゃう","usage_notes":"根据原て形结尾选择「ちゃう」或「じゃう」。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N4","common_mistakes":["「読んでしまう」要变成「読んじゃう」，不是「読んちゃう」。"],"base_type":"verb","required_form":"てしまう形","scenes":["friend_chat","family","online_chat"],"registers":["casual"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":50,"prerequisite_seed_keys":["gp_te_shimau","gp_casual_spoken"],"examples":[{"jp":"電車で寝ちゃった。","zh":"在电车上睡着了。","scene":"friend_chat","register":"casual"},{"jp":"このケーキ、全部食べちゃう？","zh":"这块蛋糕要全吃掉吗？","scene":"family","register":"casual"},{"jp":"大事なメールを消しちゃった。","zh":"不小心删掉了重要邮件。","scene":"online_chat","register":"casual"}]},
  {"seed_key":"gp_ext_toku_contraction","grammar_point":"〜とく","canonical_form":"〜ておく","sense_key":"teoku_casual_contraction_toku","form_group_slug":"te_oku","point_type":"conjugation","primary_node_slug":"casual_spoken_register","secondary_node_slugs":["progressive_state_experience_completion"],"sub_category":"准备表达缩约","core_meaning":"在随便口语中把「〜ておく」缩约为「〜とく」。","natural_translation":"先……好","structure":"Vておく→Vとく；Vでおく→Vどく","usage_notes":"「読んでおく」缩约为「読んどく」；正式场合保留完整形式。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N4","common_mistakes":["浊音て形要使用「どく」，不能一律变成「とく」。"],"base_type":"verb","required_form":"ておく形","scenes":["friend_chat","family","workplace"],"registers":["casual"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":60,"prerequisite_seed_keys":["gp_te_oku","gp_casual_spoken"],"examples":[{"jp":"席、取っとくね。","zh":"我先占好座位哦。","scene":"friend_chat","register":"casual"},{"jp":"あとで使うから、ここに置いといて。","zh":"之后要用，先放这里。","scene":"family","register":"casual"},{"jp":"資料は先に読んどく。","zh":"资料我会先读好。","scene":"workplace","register":"casual"}]},
  {"seed_key":"gp_ext_nakya_contraction","grammar_point":"〜なきゃ","canonical_form":"〜なければ","sense_key":"nakereba_casual_contraction_nakya","form_group_slug":"obligation_contractions","point_type":"conjugation","primary_node_slug":"casual_spoken_register","secondary_node_slugs":["obligation_necessity_unnecessity","conditions_and_hypotheses"],"sub_category":"义务缩约","core_meaning":"在随便口语中把「〜なければ」缩约，常省略后面的义务表达。","natural_translation":"得……／必须……","structure":"Vなければ（ならない）→Vなきゃ","usage_notes":"句末省略时仍表达“必须”；正式或礼貌场景使用完整义务形式。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N4","common_mistakes":["不能对客户用「〜なきゃ」表达规定。"],"base_type":"verb","required_form":"ない形","scenes":["friend_chat","family","online_chat"],"registers":["casual"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":70,"prerequisite_seed_keys":["gp_nai_form","gp_nakereba_naranai"],"examples":[{"jp":"もう帰らなきゃ。","zh":"我得回去了。","scene":"friend_chat","register":"casual"},{"jp":"明日早いから、寝なきゃ。","zh":"明天要早起，得睡了。","scene":"family","register":"casual"},{"jp":"レポート、今日中に出さなきゃ。","zh":"报告今天之内得交。","scene":"online_chat","register":"casual"}]},
  {"seed_key":"gp_ext_tteiu_contraction","grammar_point":"〜っていう","canonical_form":"〜という","sense_key":"toiu_casual_contraction_tteiu","form_group_slug":"to_iu","point_type":"conjugation","primary_node_slug":"casual_spoken_register","secondary_node_slugs":["quotation_reporting_topic","noun_modifying_clauses"],"sub_category":"引用说明缩约","core_meaning":"在随便口语中把「〜という」缩约，用于名称、定义或转述。","natural_translation":"叫作……／所谓……","structure":"〜という → 〜っていう","usage_notes":"后面可接名词，也可用于口语转述；正式书面语保留「という」。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N4","common_mistakes":["不要把所有引用助词「と」都机械改成「っていう」。"],"base_type":"clause","required_form":"引用内容","scenes":["friend_chat","online_chat","daily_life"],"registers":["casual"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":80,"prerequisite_seed_keys":["gp_to_iu","gp_tte_quotation"],"examples":[{"jp":"田中さんっていう人、知ってる？","zh":"你认识一个叫田中的人吗？","scene":"friend_chat","register":"casual"},{"jp":"明日は休みだっていう話、本当？","zh":"说明天放假的消息是真的吗？","scene":"online_chat","register":"casual"},{"jp":"これは「御朱印」っていうものだよ。","zh":"这个叫作御朱印。","scene":"travel","register":"casual"}]},
  {"seed_key":"gp_ext_ja_contraction","grammar_point":"じゃ（では的缩约）","canonical_form":"では","sense_key":"dewa_casual_contraction_ja","form_group_slug":"copula_contractions","point_type":"conjugation","primary_node_slug":"casual_spoken_register","secondary_node_slugs":["adjective_noun_conjugation","plain_polite_style"],"sub_category":"判断句缩约","core_meaning":"在口语中把名词或な形容词后的「では」缩约为「じゃ」。","natural_translation":"不是……／那么……","structure":"ではない→じゃない；では→じゃ","usage_notes":"在日常礼貌会话也可能出现「じゃありません」，正式书面语使用「では」。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N5","common_mistakes":["不要在正式文件中使用口语缩约「じゃ」。"],"base_type":"noun","required_form":"名词或な形容词词干","scenes":["friend_chat","family","daily_life"],"registers":["casual","polite"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":90,"prerequisite_seed_keys":["gp_noun_negative","gp_plain_style"],"examples":[{"jp":"それ、私のじゃないよ。","zh":"那个不是我的。","scene":"friend_chat","register":"casual"},{"jp":"今日は休みじゃありません。","zh":"今天不是休息日。","scene":"daily_life","register":"polite"},{"jp":"じゃ、また明日。","zh":"那么，明天见。","scene":"friend_chat","register":"casual"}]},
  {"seed_key":"gp_ext_nakucha_contraction","grammar_point":"〜なくちゃ","canonical_form":"〜なくては","sense_key":"nakuteha_casual_contraction_nakucha","form_group_slug":"obligation_contractions","point_type":"conjugation","primary_node_slug":"casual_spoken_register","secondary_node_slugs":["obligation_necessity_unnecessity"],"sub_category":"义务缩约","core_meaning":"在随便口语中把「〜なくては」缩约，常省略「いけない／ならない」。","natural_translation":"得……／必须……","structure":"Vなくては（いけない）→Vなくちゃ","usage_notes":"和「〜なきゃ」接近；都是亲近口语，不适合正式规定。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N4","common_mistakes":["不要误解为许可；它表达义务。"],"base_type":"verb","required_form":"ない形","scenes":["friend_chat","family","online_chat"],"registers":["casual"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":100,"prerequisite_seed_keys":["gp_nai_form","gp_naito_ikenai"],"examples":[{"jp":"そろそろ行かなくちゃ。","zh":"差不多得走了。","scene":"friend_chat","register":"casual"},{"jp":"部屋を片づけなくちゃ。","zh":"得收拾房间了。","scene":"family","register":"casual"},{"jp":"返信しなくちゃと思ってた。","zh":"我一直想着得回复。","scene":"online_chat","register":"casual"}]},
  {"seed_key":"gp_ext_jan","grammar_point":"〜じゃん","canonical_form":"〜じゃない","sense_key":"jan_casual_shared_assertion","form_group_slug":"janai","point_type":"grammar_pattern","primary_node_slug":"sentence_final_nuance","secondary_node_slugs":["casual_spoken_register","sentence_final_particles"],"sub_category":"口语确认与强调","core_meaning":"在亲近口语中指出对方也该知道的事实，或表达发现、反驳和赞叹。","natural_translation":"不是……嘛／这不……吗","structure":"普通形 + じゃん","usage_notes":"不是普通否定；对不熟悉的人可能显得强势或轻佻。","practicality":"A","spoken_or_written":"spoken","jlpt_level":"N3","common_mistakes":["不要按字面把「じゃん」一律理解为否定。"],"base_type":"clause","required_form":"普通形","scenes":["friend_chat","family","online_chat"],"registers":["casual"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":110,"prerequisite_seed_keys":["gp_plain_style","gp_ext_ja_contraction"],"examples":[{"jp":"この店、けっこう安いじゃん。","zh":"这家店不是挺便宜的嘛。","scene":"friend_chat","register":"casual"},{"jp":"言ったじゃん、今日は休みだって。","zh":"我不是说了吗，今天放假。","scene":"family","register":"casual"},{"jp":"その写真、すごくいいじゃん！","zh":"那张照片很棒嘛！","scene":"online_chat","register":"casual"}]},
  {"seed_key":"gp_ext_kke","grammar_point":"〜っけ","canonical_form":"〜っけ","sense_key":"kke_memory_check","form_group_slug":"sentence_final_kke","point_type":"particle","primary_node_slug":"sentence_final_nuance","secondary_node_slugs":["casual_spoken_register","sentence_final_particles"],"sub_category":"回忆确认","core_meaning":"在随便口语中回想自己记不清的信息并向对方确认。","natural_translation":"来着／是不是……来着","structure":"普通形 + っけ","usage_notes":"多用于自己曾经知道但暂时忘记的内容，不是首次询问。","practicality":"A","spoken_or_written":"spoken","jlpt_level":"N3","common_mistakes":["正式询问陌生信息时不用「っけ」。"],"base_type":"clause","required_form":"普通形","scenes":["friend_chat","family","workplace"],"registers":["casual"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":120,"prerequisite_seed_keys":["gp_plain_style","gp_kana"],"examples":[{"jp":"会議って何時からだっけ？","zh":"会议是几点开始来着？","scene":"workplace","register":"casual"},{"jp":"この店、前にも来たっけ？","zh":"我们以前来过这家店吗？","scene":"friend_chat","register":"casual"},{"jp":"鍵、どこに置いたっけ。","zh":"钥匙放哪儿来着。","scene":"family","register":"casual"}]},
  {"seed_key":"gp_ext_tteba","grammar_point":"〜ってば","canonical_form":"〜ってば","sense_key":"tteba_repeated_insistence","form_group_slug":"tteba","point_type":"grammar_pattern","primary_node_slug":"sentence_final_nuance","secondary_node_slugs":["casual_spoken_register","quotation_reporting_topic"],"sub_category":"重复催促与坚持","core_meaning":"在亲近口语中重复自己的话、催促对方或强调称呼。","natural_translation":"都说了……／喂……","structure":"引用内容/称呼 + ってば","usage_notes":"带不耐烦或强烈亲密感，仅适合关系近的对象。","practicality":"B","spoken_or_written":"spoken","jlpt_level":"N3","common_mistakes":["对客户、老师或上级使用会非常失礼。"],"base_type":"clause","required_form":"引用内容或称呼","scenes":["friend_chat","family"],"registers":["casual","rough"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":130,"prerequisite_seed_keys":["gp_tte_quotation","gp_casual_spoken"],"examples":[{"jp":"もう行くってば！","zh":"都说了我要去啦！","scene":"family","register":"casual"},{"jp":"大丈夫だってば。","zh":"都说了没事啦。","scene":"friend_chat","register":"casual"},{"jp":"ねえ、お兄ちゃんってば。","zh":"喂，哥哥啦。","scene":"family","register":"casual"}]},
  {"seed_key":"gp_ext_mon","grammar_point":"〜もの／〜もん","canonical_form":"〜もの","sense_key":"mono_mon_casual_justification","form_group_slug":"sentence_final_mono","point_type":"grammar_pattern","primary_node_slug":"sentence_final_nuance","secondary_node_slugs":["casual_spoken_register","reasons_and_explanations"],"sub_category":"口语辩解","core_meaning":"用带情绪的语气说明理由、辩解或撒娇。","natural_translation":"因为嘛／可是……嘛","structure":"普通形 + もの；口语缩约为 + もん","usage_notes":"「もん」更口语、孩子气；正式理由说明使用「ので／から」。","practicality":"A","spoken_or_written":"spoken","jlpt_level":"N3","common_mistakes":["需要客观正式说明原因时不要用「もん」。"],"base_type":"clause","required_form":"普通形","scenes":["friend_chat","family","online_chat"],"registers":["casual","soft"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":140,"prerequisite_seed_keys":["gp_kara_reason","gp_casual_spoken"],"examples":[{"jp":"行きたくない。疲れてるんだもん。","zh":"不想去，因为我累了嘛。","scene":"friend_chat","register":"casual"},{"jp":"知らなかったんだもん。","zh":"因为我不知道嘛。","scene":"family","register":"casual"},{"jp":"だって、本当に欲しかったんだもん。","zh":"可是我真的很想要嘛。","scene":"online_chat","register":"casual"}]},
  {"seed_key":"gp_ext_wake_question","grammar_point":"〜わけ？","canonical_form":"〜わけ","sense_key":"wake_casual_question_inference","form_group_slug":"wake","point_type":"grammar_pattern","primary_node_slug":"sentence_final_nuance","secondary_node_slugs":["casual_spoken_register","inference_judgment_sources"],"sub_category":"口语追问推论","core_meaning":"在随便口语中根据前文追问“也就是说是这种情况吗”。","natural_translation":"所以说……吗／难道……吗","structure":"普通形 + わけ？","usage_notes":"可能带惊讶或质问；正式确认应使用「ということですか」。","practicality":"A","spoken_or_written":"spoken","jlpt_level":"N3","common_mistakes":["语气容易变成质问，对不熟悉的人应避免。"],"base_type":"clause","required_form":"普通形","scenes":["friend_chat","family","online_chat"],"registers":["casual"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":150,"prerequisite_seed_keys":["gp_plain_style","gp_tsumari"],"examples":[{"jp":"じゃあ、今日は来ないわけ？","zh":"那么，今天是不来了吗？","scene":"friend_chat","register":"casual"},{"jp":"全部一人でやったわけ？","zh":"这些全是你一个人做的吗？","scene":"family","register":"casual"},{"jp":"つまり、もう決めたってわけ？","zh":"也就是说，你已经决定了？","scene":"online_chat","register":"casual"}]},
  {"seed_key":"gp_ext_kashira","grammar_point":"〜かしら","canonical_form":"〜かしら","sense_key":"kashira_soft_wonder","form_group_slug":"sentence_final_kashira","point_type":"particle","primary_node_slug":"sentence_final_nuance","secondary_node_slugs":["sentence_final_particles","casual_spoken_register"],"sub_category":"柔和自问","core_meaning":"较柔和地表达自问、不确定或轻微询问。","natural_translation":"不知道……呢／会不会……","structure":"普通形 + かしら","usage_notes":"现代会话中常带女性口语或较柔和印象；中性表达可用「かな」。","practicality":"B","spoken_or_written":"spoken","jlpt_level":"N3","common_mistakes":["不要不顾人物语气机械替换「かな」。"],"base_type":"clause","required_form":"普通形","scenes":["friend_chat","family","daily_life"],"registers":["casual","soft"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":160,"prerequisite_seed_keys":["gp_kana","gp_plain_style"],"examples":[{"jp":"明日は晴れるかしら。","zh":"不知道明天会不会晴。","scene":"daily_life","register":"soft"},{"jp":"この服、私に似合うかしら。","zh":"这件衣服适合我吗？","scene":"shopping","register":"soft"},{"jp":"もう着いたかしら。","zh":"不知道是不是已经到了。","scene":"family","register":"casual"}]},
  {"seed_key":"gp_ext_ka_to_omotta","grammar_point":"〜かと思った","canonical_form":"〜かと思った","sense_key":"ka_to_omotta_mistaken_impression","form_group_slug":"to_omou","point_type":"grammar_pattern","primary_node_slug":"sentence_final_nuance","secondary_node_slugs":["inference_judgment_sources","casual_spoken_register"],"sub_category":"一度误以为","core_meaning":"表示一度产生某种判断，随后发现与事实不同或差点发生。","natural_translation":"还以为……／差点以为……","structure":"普通形 + かと思った","usage_notes":"常和意外、安心或轻微责备搭配。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N3","common_mistakes":["如果判断现在仍成立，应使用「と思う」，不是过去的「と思った」。"],"base_type":"clause","required_form":"普通形","scenes":["friend_chat","family","workplace"],"registers":["casual","polite"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":170,"prerequisite_seed_keys":["gp_to_omou","gp_ta_form"],"examples":[{"jp":"電車に乗り遅れたかと思った。","zh":"还以为没赶上电车。","scene":"transportation","register":"casual"},{"jp":"今日は休みかと思いました。","zh":"我还以为今天休息。","scene":"workplace","register":"polite"},{"jp":"急に返事がないから、何かあったかと思ったよ。","zh":"突然没回复，我还以为出什么事了。","scene":"friend_chat","register":"casual"}]},
  {"seed_key":"gp_ext_tari_shite","grammar_point":"〜たりして","canonical_form":"〜たりして","sense_key":"tari_shite_playful_possibility","form_group_slug":"tari","point_type":"grammar_pattern","primary_node_slug":"sentence_final_nuance","secondary_node_slugs":["inference_judgment_sources","casual_spoken_register"],"sub_category":"玩笑式可能","core_meaning":"轻松、试探或开玩笑地提出一种可能。","natural_translation":"说不定……呢／会不会……","structure":"Vた形 + りして","usage_notes":"语气比直接推测更轻，常用于关系亲近的会话。","practicality":"A","spoken_or_written":"spoken","jlpt_level":"N3","common_mistakes":["正式风险判断不要使用玩笑感较强的「たりして」。"],"base_type":"verb","required_form":"た形","scenes":["friend_chat","family","online_chat"],"registers":["casual","soft"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":180,"prerequisite_seed_keys":["gp_ta_form","gp_kamoshirenai"],"examples":[{"jp":"明日、急に休みになったりして。","zh":"说不定明天突然放假呢。","scene":"workplace","register":"casual"},{"jp":"実は彼も来たかったりして。","zh":"说不定其实他也想来。","scene":"friend_chat","register":"casual"},{"jp":"宝くじ、当たったりしてね。","zh":"说不定彩票中了呢。","scene":"family","register":"casual"}]},
