  {"seed_key":"gp_ext_to_iu_ka","grammar_point":"〜というか／〜っていうか","canonical_form":"〜というか","sense_key":"to_iu_ka_reformulation","form_group_slug":"to_iu_ka","point_type":"discourse_marker","primary_node_slug":"example_summary_topic_shift","secondary_node_slugs":["casual_spoken_register","sentence_final_nuance"],"sub_category":"改口与重新表述","core_meaning":"修正刚才的说法，寻找更准确的表达，或缓和评价。","natural_translation":"或者说……／怎么说呢","structure":"句子 + というか；口语 + っていうか","usage_notes":"可用于自我修正，但频繁使用会使表达显得拖沓。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N3","common_mistakes":["不能用它替代所有转折连接；重点是重新表述。"],"base_type":"clause","required_form":"完整句或评价词","scenes":["friend_chat","workplace","online_chat"],"registers":["casual","polite","soft"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":200,"prerequisite_seed_keys":["gp_to_iu","gp_tsumari"],"examples":[{"jp":"難しいというか、時間が足りないんです。","zh":"与其说难，不如说时间不够。","scene":"workplace","register":"polite"},{"jp":"彼は静かっていうか、あまり話さない。","zh":"他与其说安静，不如说不太说话。","scene":"friend_chat","register":"casual"},{"jp":"怒ってるというか、少し困ってる。","zh":"与其说生气，不如说有点困扰。","scene":"online_chat","register":"casual"}]},
  {"seed_key":"gp_ext_kana_to_omotte","grammar_point":"〜かなと思って","canonical_form":"〜かなと思って","sense_key":"kana_to_omotte_soft_intention","form_group_slug":"kana","point_type":"grammar_pattern","primary_node_slug":"sentence_final_nuance","secondary_node_slugs":["purpose_and_plans","casual_spoken_register"],"sub_category":"柔和说明想法","core_meaning":"用不确定、自言自语式的形式柔和说明自己的打算、猜测或提议。","natural_translation":"我在想要不要……／想着也许……","structure":"普通形 + かなと思って","usage_notes":"常作为后续请求或行动的背景，比直接说意图更柔和。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N3","common_mistakes":["需要明确承诺时不要用过度含糊的「かなと思って」。"],"base_type":"clause","required_form":"普通形","scenes":["friend_chat","workplace","school"],"registers":["casual","polite","soft"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":210,"prerequisite_seed_keys":["gp_kana","gp_to_omou"],"examples":[{"jp":"週末、映画を見に行こうかなと思ってる。","zh":"我在想周末要不要去看电影。","scene":"friend_chat","register":"casual"},{"jp":"少し早めに伺おうかなと思っているんですが。","zh":"我在想是不是稍微早点过去。","scene":"workplace","register":"polite"},{"jp":"先生に相談してみようかなと思って。","zh":"我在想要不要找老师商量一下。","scene":"school","register":"casual"}]},
  {"seed_key":"gp_ext_ndakedo","grammar_point":"〜んだけど","canonical_form":"〜んだけど","sense_key":"ndakedo_casual_lead_in","form_group_slug":"ndesu","point_type":"grammar_pattern","primary_node_slug":"sentence_final_nuance","secondary_node_slugs":["casual_spoken_register","contrast_concession_comparison"],"sub_category":"口语铺垫","core_meaning":"用说明背景加未完转折，柔和地引出请求、问题或新话题。","natural_translation":"是这样的……／不过……","structure":"普通形 + んだけど；名词/な形容词 + なんだけど","usage_notes":"后项可省略，让对方从语境推断请求；正式场景使用「んですが」。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N4","common_mistakes":["对方无法从语境理解时不要只说到「んだけど」就停止。"],"base_type":"clause","required_form":"普通形","scenes":["friend_chat","family","online_chat"],"registers":["casual","soft"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":220,"prerequisite_seed_keys":["gp_ndesu","gp_kedo"],"examples":[{"jp":"ちょっと聞きたいことがあるんだけど。","zh":"我有点事情想问。","scene":"friend_chat","register":"casual"},{"jp":"明日の予定なんだけど、時間を変えられる？","zh":"关于明天的安排，能改一下时间吗？","scene":"online_chat","register":"casual"},{"jp":"この箱、重いんだけど、手伝ってくれる？","zh":"这个箱子很重，能帮帮我吗？","scene":"family","register":"casual"}]},
  {"seed_key":"gp_ext_response_markers","grammar_point":"会话回应（そうなんだ／なるほど／たしかに）","canonical_form":"会话回应表达","sense_key":"conversation_response_markers","form_group_slug":"conversation_markers","point_type":"discourse_marker","primary_node_slug":"additive_progression","secondary_node_slugs":["casual_spoken_register","sentence_final_nuance"],"sub_category":"理解与共感回应","core_meaning":"根据理解程度表达接收新信息、理解原因或赞同判断。","natural_translation":"原来如此／确实","structure":"そうなんだ；なるほど；たしかに + 评价","usage_notes":"「そうなんだ」接收信息；「なるほど」表示理解逻辑；「たしかに」承认对方判断有道理。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N4","common_mistakes":["商务场合对上级频繁说「なるほど」可能显得在评判，可改为「おっしゃるとおりです」。"],"base_type":"clause","required_form":"独立回应","scenes":["friend_chat","workplace","family"],"registers":["casual","polite"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":230,"prerequisite_seed_keys":["gp_casual_spoken"],"examples":[{"jp":"来月引っ越すんだ。—そうなんだ。","zh":"下个月要搬家。—原来如此。","scene":"friend_chat","register":"casual"},{"jp":"この順番なら早く終わります。—なるほど。","zh":"按这个顺序就能早点结束。—原来如此。","scene":"workplace","register":"polite"},{"jp":"たしかに、その方法のほうが分かりやすいね。","zh":"确实，那个方法更容易懂。","scene":"family","register":"casual"}]},
  {"seed_key":"gp_ext_conversation_connectors","grammar_point":"会话连接（それで／だから／ちなみに）","canonical_form":"会话连接表达","sense_key":"conversation_connectors","form_group_slug":"conversation_markers","point_type":"discourse_marker","primary_node_slug":"additive_progression","secondary_node_slugs":["cause_result_connections","example_summary_topic_shift"],"sub_category":"推进与补充","core_meaning":"在会话中继续追问结果、说明结论或补充相关信息。","natural_translation":"然后呢／所以／顺便说","structure":"それで、句子；だから、句子；ちなみに、句子","usage_notes":"「それで」承接前文经过或追问结果；「だから」给出结论；「ちなみに」补充相关信息。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N4","common_mistakes":["不要在对方说明尚未结束时用「それで？」显得催促。"],"base_type":"clause","required_form":"句首独立连接","scenes":["friend_chat","workplace","online_chat"],"registers":["casual","polite"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":240,"prerequisite_seed_keys":["gp_soshite","gp_sono_tame","gp_tokorode"],"examples":[{"jp":"それで、結局どうなったの？","zh":"然后呢，最后怎么样了？","scene":"friend_chat","register":"casual"},{"jp":"電車が遅れました。だから、少し遅刻します。","zh":"电车晚点了，所以我会迟到一点。","scene":"workplace","register":"polite"},{"jp":"ちなみに、参加費は無料です。","zh":"顺便说一下，参加费免费。","scene":"online_chat","register":"polite"}]},
  {"seed_key":"gp_ext_fillers_stance","grammar_point":"口语填充与立场（なんか／まあ／別に／やっぱり）","canonical_form":"口语填充与立场表达","sense_key":"casual_fillers_and_stance","form_group_slug":"conversation_markers","point_type":"discourse_marker","primary_node_slug":"sentence_final_nuance","secondary_node_slugs":["casual_spoken_register","word_order_focus"],"sub_category":"犹豫与立场调节","core_meaning":"用高频短语表达寻找词语、暂时保留、无特别意见或重新确认立场。","natural_translation":"那个／嗯／没什么／果然","structure":"なんか；まあ；別に；やっぱり + 句子","usage_notes":"这些表达高度依赖语调；「別に」单独回答可能显得冷淡。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N4","common_mistakes":["不要把填充词逐字翻译，也不要在正式发言中过量使用。"],"base_type":"clause","required_form":"独立副词或回应","scenes":["friend_chat","family","online_chat"],"registers":["casual","soft"],"stage_slug":"natural_advanced_use","module_slug":"social_conversation","sort_order":250,"prerequisite_seed_keys":["gp_casual_spoken"],"examples":[{"jp":"なんか、今日は静かだね。","zh":"总觉得今天很安静呢。","scene":"friend_chat","register":"casual"},{"jp":"まあ、今回はこれでいいんじゃない？","zh":"嗯，这次这样不也挺好吗？","scene":"family","register":"casual"},{"jp":"別に嫌じゃないけど、やっぱり家にいたい。","zh":"也不是讨厌，不过果然还是想待在家。","scene":"online_chat","register":"casual"}]},
