  {"seed_key":"gp_ext_wo_okaeshi_itashimasu","grammar_point":"〜をお返しいたします","canonical_form":"〜をお返しいたします","sense_key":"service_okaeshi_itashimasu","form_group_slug":"service_handling","point_type":"collocation","primary_node_slug":"formulaic_scene_expressions","secondary_node_slugs":["honorifics_and_politeness","noun_verb_collocations"],"sub_category":"礼貌返还","core_meaning":"服务方礼貌表示返还证件、物品、找零或资料。","natural_translation":"把……还给您","structure":"名词 + をお返しいたします","usage_notes":"与「お預かりします」形成服务流程中的收取—返还对。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N3","common_mistakes":["己方归还客户物品时不要使用抬高客户动作的尊敬语。"],"base_type":"noun","required_form":"物品、证件或找零","scenes":["shopping","government_office","customer_service"],"registers":["customer","formal"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":360,"prerequisite_seed_keys":["gp_ext_wo_oazukari_shimasu"],"examples":[{"jp":"五千円のお返しでございます。","zh":"找您五千日元。","scene":"shopping","register":"customer"},{"jp":"確認が終わりましたので、在留カードをお返しいたします。","zh":"确认结束，现将在留卡还给您。","scene":"government_office","register":"formal"},{"jp":"修理が完了しましたら、商品をお返しいたします。","zh":"维修完成后将商品返还给您。","scene":"customer_service","register":"customer"}]},
  {"seed_key":"gp_ext_shoushou_omachi_kudasai","grammar_point":"少々お待ちください","canonical_form":"少々お待ちください","sense_key":"service_shoushou_omachi_kudasai","form_group_slug":"service_waiting","point_type":"collocation","primary_node_slug":"formulaic_scene_expressions","secondary_node_slugs":["requests_permission_advice","honorifics_and_politeness"],"sub_category":"请求稍候","core_meaning":"服务、电话或商务场景中礼貌请求对方短暂等待。","natural_translation":"请稍等","structure":"少々 + お待ちください","usage_notes":"等待较长时应说明预计时间或原因，并在回来后使用等待致歉。","practicality":"S","spoken_or_written":"spoken","jlpt_level":"N3","common_mistakes":["不能让对方无限等待而不提供时间或后续说明。"],"base_type":"verb","required_form":"固定表达","scenes":["phone_call","customer_service","restaurant"],"registers":["customer","business","formal"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":370,"prerequisite_seed_keys":["gp_te_kudasai","gp_ext_o_go_ninaru"],"examples":[{"jp":"担当者におつなぎしますので、少々お待ちください。","zh":"现在为您转接负责人，请稍等。","scene":"phone_call","register":"business"},{"jp":"在庫を確認しますので、少々お待ちください。","zh":"我确认一下库存，请稍等。","scene":"customer_service","register":"customer"},{"jp":"ただいまお席を準備しております。少々お待ちください。","zh":"正在为您准备座位，请稍等。","scene":"restaurant","register":"customer"}]},
