  {"seed_key":"gp_ext_itashikanemasu","grammar_point":"〜いたしかねます","canonical_form":"〜いたしかねます","sense_key":"itashikanemasu_humble_refusal","form_group_slug":"kaneru","point_type":"grammar_pattern","primary_node_slug":"honorifics_and_politeness","secondary_node_slugs":["ability_potential_difficulty","honorific_humble_language"],"sub_category":"郑重拒绝","core_meaning":"用谦让动词「いたす」郑重表示己方无法接受或处理。","natural_translation":"恕无法……","structure":"汉语词干 + いたしかねます","usage_notes":"比「〜かねます」更郑重，客服书面回复中高频。","practicality":"A","spoken_or_written":"both","jlpt_level":"N2","common_mistakes":["不要只说拒绝；正式服务沟通应补充理由或可行选项。"],"base_type":"noun","required_form":"汉语动作词干","scenes":["customer_service","email","workplace"],"registers":["customer","business","formal","written"],"stage_slug":"natural_advanced_use","module_slug":"workplace_service","sort_order":390,"prerequisite_seed_keys":["gp_ext_kanemasu","gp_humble_language"],"examples":[{"jp":"返品はいたしかねますので、ご了承ください。","zh":"恕不接受退货，敬请谅解。","scene":"customer_service","register":"customer"},{"jp":"期日を過ぎた申請は受理いたしかねます。","zh":"逾期申请恕不受理。","scene":"government_office","register":"formal"},{"jp":"その条件では契約いたしかねます。","zh":"在该条件下恕难签约。","scene":"workplace","register":"business"}]},
