  {"seed_key":"gp_ext_ni_taishi_connective","grammar_point":"〜に対し（书面连接）","canonical_form":"〜に対し","sense_key":"ni_taishi_written_contrast","form_group_slug":"ni_taishite","point_type":"grammar_pattern","primary_node_slug":"contrast_concession_comparison","secondary_node_slugs":["compound_particles","adversative_connections"],"sub_category":"书面对照","core_meaning":"在书面语中把两个对象、数据或情况直接对照。","natural_translation":"相对于……／而……","structure":"名词/普通形 + のに対し；名词 + に対し","usage_notes":"本条是连接对照用法；表示动作对象的「に対して」是另一功能。","practicality":"A","spoken_or_written":"written","jlpt_level":"N2","common_mistakes":["不要把对照用法和“对某人采取态度”的对象用法混淆。"],"base_type":"clause","required_form":"名词或普通形","scenes":["workplace","school","government_office"],"registers":["written","academic","news"],"stage_slug":"natural_advanced_use","module_slug":"media_formal","sort_order":140,"prerequisite_seed_keys":["gp_ni_taishite","gp_ippoude"],"examples":[{"jp":"前年が赤字だったのに対し、今年は黒字です。","zh":"前年亏损，而今年盈利。","scene":"workplace","register":"written"},{"jp":"都市部では人口が増えたのに対し、地方では減少しました。","zh":"城市人口增加，而地方人口减少。","scene":"government_office","register":"news"},{"jp":"兄が社交的なのに対し、弟は静かです。","zh":"哥哥外向，而弟弟安静。","scene":"school","register":"academic"}]},
