  {"seed_key":"gp_ext_wo_taishou_to_shita","grammar_point":"〜を対象とした","canonical_form":"〜を対象とした","sense_key":"wo_taishou_to_shita_targeted_at","form_group_slug":"formal_attributive","point_type":"grammar_pattern","primary_node_slug":"noun_modifying_clauses","secondary_node_slugs":["noun_verb_collocations"],"sub_category":"对象限定修饰","core_meaning":"说明活动、制度、调查或服务以某群体或事物为对象。","natural_translation":"以……为对象的","structure":"名词 + を対象とした + 名词","usage_notes":"常见于招募、政策、研究和服务说明。","practicality":"A","spoken_or_written":"written","jlpt_level":"N2","common_mistakes":["动作对象与受益对象不一定相同，需看后续名词。"],"base_type":"noun","required_form":"对象名词","scenes":["school","government_office","customer_service"],"registers":["written","formal","academic"],"stage_slug":"natural_advanced_use","module_slug":"media_formal","sort_order":230,"prerequisite_seed_keys":["gp_wo","gp_rentai_modifier"],"examples":[{"jp":"留学生を対象とした説明会を開きます。","zh":"举办以留学生为对象的说明会。","scene":"school","register":"formal"},{"jp":"高齢者を対象とした支援制度です。","zh":"这是面向老年人的支援制度。","scene":"government_office","register":"written"},{"jp":"利用者を対象としたアンケートを実施します。","zh":"将实施面向用户的问卷调查。","scene":"customer_service","register":"formal"}]},
  {"seed_key":"gp_ext_wo_mokuteki_to_suru","grammar_point":"〜を目的とする","canonical_form":"〜を目的とする","sense_key":"wo_mokuteki_to_suru","form_group_slug":"formal_attributive","point_type":"grammar_pattern","primary_node_slug":"purpose_and_plans","secondary_node_slugs":["noun_modifying_clauses","noun_verb_collocations"],"sub_category":"正式目的定义","core_meaning":"正式说明活动、制度或研究的明确目的。","natural_translation":"以……为目的","structure":"名词/普通形 + ことを目的とする","usage_notes":"比个人行动目的「ために」更适合定义项目和制度。","practicality":"A","spoken_or_written":"written","jlpt_level":"N2","common_mistakes":["个人日常小目的通常不用如此正式的名词构式。"],"base_type":"clause","required_form":"名词或普通形こと","scenes":["workplace","school","government_office"],"registers":["written","formal","academic"],"stage_slug":"natural_advanced_use","module_slug":"media_formal","sort_order":240,"prerequisite_seed_keys":["gp_tame_ni","gp_koto_nominalization"],"examples":[{"jp":"この研修は社員の安全意識を高めることを目的としています。","zh":"该培训旨在提高员工的安全意识。","scene":"workplace","register":"formal"},{"jp":"交流を目的としたイベントを開催します。","zh":"将举办以交流为目的的活动。","scene":"school","register":"written"},{"jp":"地域の活性化を目的とする事業です。","zh":"这是以振兴地区为目的的事业。","scene":"government_office","register":"formal"}]},
  {"seed_key":"gp_ext_ni_motozuku","grammar_point":"〜に基づく","canonical_form":"〜に基づく","sense_key":"ni_motozuku_attributive_basis","form_group_slug":"ni_motozuku","point_type":"grammar_pattern","primary_node_slug":"noun_modifying_clauses","secondary_node_slugs":["compound_particles"],"sub_category":"依据修饰","core_meaning":"表示后面的判断、制度或行动以某事实、规则或资料为依据。","natural_translation":"基于……的","structure":"名词 + に基づく + 名词","usage_notes":"是「に基づいて」的连体形式。","practicality":"A","spoken_or_written":"written","jlpt_level":"N2","common_mistakes":["直接修饰名词时不能使用连接形「に基づいて」。"],"base_type":"noun","required_form":"依据名词","scenes":["workplace","school","government_office"],"registers":["written","formal","academic"],"stage_slug":"natural_advanced_use","module_slug":"media_formal","sort_order":250,"prerequisite_seed_keys":["gp_ext_ni_motozuite","gp_rentai_modifier"],"examples":[{"jp":"事実に基づく報告を作成してください。","zh":"请制作基于事实的报告。","scene":"workplace","register":"formal"},{"jp":"データに基づく分析が必要です。","zh":"需要基于数据的分析。","scene":"school","register":"academic"},{"jp":"法律に基づく手続きです。","zh":"这是依法进行的手续。","scene":"government_office","register":"written"}]},
  {"seed_key":"gp_ext_ni_yoru_attributive","grammar_point":"〜による","canonical_form":"〜による","sense_key":"ni_yoru_attributive_cause_agent","form_group_slug":"ni_yoru","point_type":"grammar_pattern","primary_node_slug":"noun_modifying_clauses","secondary_node_slugs":["compound_particles","reasons_and_explanations"],"sub_category":"原因、主体与手段修饰","core_meaning":"修饰名词，表示造成结果的原因、实施主体或所用手段。","natural_translation":"由……造成的／通过……的","structure":"名词 + による + 名词","usage_notes":"需根据名词关系判断是原因、主体还是手段。","practicality":"S","spoken_or_written":"written","jlpt_level":"N2","common_mistakes":["后接谓语时使用「により」，修饰名词才用「による」。"],"base_type":"noun","required_form":"原因、主体或手段名词","scenes":["workplace","transportation","government_office"],"registers":["written","news","formal"],"stage_slug":"natural_advanced_use","module_slug":"media_formal","sort_order":260,"prerequisite_seed_keys":["gp_ext_ni_yori_formal_cause","gp_rentai_modifier"],"examples":[{"jp":"大雨による被害が広がっています。","zh":"暴雨造成的损失正在扩大。","scene":"transportation","register":"news"},{"jp":"専門家による説明会を開きます。","zh":"将举办由专家主讲的说明会。","scene":"workplace","register":"formal"},{"jp":"オンラインによる申請も可能です。","zh":"也可以通过在线方式申请。","scene":"government_office","register":"written"}]},
  {"seed_key":"gp_ext_de_aru_style","grammar_point":"である体","canonical_form":"である体","sense_key":"register_de_aru_style","form_group_slug":"written_register","point_type":"register_concept","primary_node_slug":"plain_polite_style","secondary_node_slugs":["predicate_core","formal"],"sub_category":"正式书面常体","core_meaning":"以「だ／である」及普通形组织论文、报告、新闻和说明文。","natural_translation":"书面常体","structure":"名词/な形容词 + である；动词/い形容词普通形","usage_notes":"一篇文本内应保持语体一致；不是比「です・ます」天然更正确。","practicality":"S","spoken_or_written":"written","jlpt_level":"N3","common_mistakes":["不要在同一段落无理由混用「である」和「です・ます」。"],"base_type":"clause","required_form":"普通形","scenes":["school","workplace","government_office"],"registers":["written","academic","news","formal"],"stage_slug":"natural_advanced_use","module_slug":"media_formal","sort_order":270,"prerequisite_seed_keys":["gp_plain_style","gp_predicate_core"],"examples":[{"jp":"日本は四方を海に囲まれた国である。","zh":"日本是一个四面环海的国家。","scene":"school","register":"academic"},{"jp":"本調査の目的は利用実態を明らかにすることである。","zh":"本调查的目的是明确实际使用情况。","scene":"workplace","register":"written"},{"jp":"新制度の開始は四月一日である。","zh":"新制度的开始日期是四月一日。","scene":"government_office","register":"formal"}]},
  {"seed_key":"gp_ext_passive_information_focus","grammar_point":"无主语被动与信息焦点","canonical_form":"无主语被动与信息焦点","sense_key":"syntax_passive_information_focus","form_group_slug":"information_structure","point_type":"syntax_concept","primary_node_slug":"word_order_focus","secondary_node_slugs":["derived_potential_passive_causative","ellipsis_context_completion"],"sub_category":"媒体句法","core_meaning":"媒体和正式文本通过省略施事者、使用被动，把事件或结果置于信息焦点。","natural_translation":"据……／……已被……","structure":"对象 + が/は + V被动形；施事者省略或用「によって」标记","usage_notes":"省略施事者应是因为未知、不重要或可由语境恢复，而非故意逃避责任。","practicality":"A","spoken_or_written":"written","jlpt_level":"N2","common_mistakes":["并非所有中文被动都应翻译成日语被动，也不能让责任主体无故消失。"],"base_type":"clause","required_form":"被动形","scenes":["workplace","government_office","school"],"registers":["news","written","academic"],"stage_slug":"natural_advanced_use","module_slug":"media_formal","sort_order":280,"prerequisite_seed_keys":["gp_passive_form","gp_ellipsis","gp_word_order_focus"],"examples":[{"jp":"新しい計画が発表されました。","zh":"新计划已经公布。","scene":"workplace","register":"news"},{"jp":"駅前で新しい施設が建設されています。","zh":"车站前正在建设新设施。","scene":"government_office","register":"news"},{"jp":"この理論は多くの研究で支持されています。","zh":"这一理论得到许多研究的支持。","scene":"school","register":"academic"}]},
  {"seed_key":"gp_ext_media_data_expressions","grammar_point":"媒体数据表达","canonical_form":"媒体数据表达","sense_key":"collocation_media_quantitative_reporting","form_group_slug":"media_collocations","point_type":"collocation","primary_node_slug":"noun_verb_collocations","secondary_node_slugs":["comparison_degree_scope","formulaic_scene_expressions"],"sub_category":"数量变化报道","core_meaning":"用固定搭配准确报道数量达到、占比、累计、维持或超过某一水平。","natural_translation":"达到／占／多达／停留在／超过或低于／同比增减","structure":"数量に達する；数量に上る；割合を占める；数量にとどまる；基准を上回る/下回る；前年比で増減する","usage_notes":"每个谓语选择的主语和数量类型不同，应连同真实数据语境学习。","practicality":"S","spoken_or_written":"written","jlpt_level":"N2","common_mistakes":["不要把所有数值变化都只翻译成「増える／減る」，需区分达到、占比和累计。"],"base_type":"noun","required_form":"数量、比例或基准","scenes":["workplace","government_office","school"],"registers":["news","written","business","academic"],"stage_slug":"natural_advanced_use","module_slug":"media_formal","sort_order":290,"prerequisite_seed_keys":["gp_yori_comparison","gp_ext_counters_quantity"],"examples":[{"jp":"利用者は十万人に達し、前年を二割上回りました。","zh":"使用人数达到十万，比去年高出两成。","scene":"workplace","register":"news"},{"jp":"外国人参加者は全体の三割を占めています。","zh":"外国参加者占整体的三成。","scene":"school","register":"academic"},{"jp":"被害額は五億円に上る一方、復旧率は六割にとどまりました。","zh":"损失金额高达五亿日元，而修复率仅停留在六成。","scene":"government_office","register":"news"}]}
