[
  {"seed_key":"gp_ext_hazu_da","grammar_point":"〜はずだ","canonical_form":"〜はずだ","sense_key":"hazu_da_reasonable_expectation","form_group_slug":"hazu","point_type":"grammar_pattern","primary_node_slug":"inference_judgment_sources","secondary_node_slugs":["sentence_final_nuance"],"sub_category":"有依据的预期","core_meaning":"根据已知事实、计划或逻辑，判断某事理应成立。","natural_translation":"应该……／按理说……","structure":"普通形 + はずだ；名词の/な形容词な + はずだ","usage_notes":"表达推理上的高概率，不是义务“应该做”。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["不要把建议或道德义务翻成「はずだ」，那通常用「べき」。"],"base_type":"clause","required_form":"普通形","scenes":["daily_life","workplace","travel"],"registers":["casual","polite","written"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":10,"prerequisite_seed_keys":["gp_plain_style","gp_kamoshirenai"],"examples":[{"jp":"田中さんはもう駅に着いているはずです。","zh":"田中应该已经到车站了。","scene":"workplace","register":"polite"},{"jp":"この道をまっすぐ行けば、右側にあるはずだ。","zh":"沿这条路直走，应该就在右边。","scene":"travel","register":"casual"},{"jp":"予約したので、席は確保されているはずです。","zh":"因为预约了，座位应该已经保留。","scene":"restaurant","register":"polite"}]},
  {"seed_key":"gp_ext_hazu_ga_nai","grammar_point":"〜はずがない","canonical_form":"〜はずがない","sense_key":"hazu_ga_nai_logical_impossibility","form_group_slug":"hazu","point_type":"grammar_pattern","primary_node_slug":"inference_judgment_sources","secondary_node_slugs":["sentence_final_nuance"],"sub_category":"逻辑上不可能","core_meaning":"根据说话人掌握的事实，强烈判断某事不可能成立。","natural_translation":"不可能……／按理不会……","structure":"普通形 + はずがない","usage_notes":"置信度很高；信息不足时使用「かもしれない／とは思えない」更谨慎。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["不要在缺乏依据时武断使用。"],"base_type":"clause","required_form":"普通形","scenes":["daily_life","workplace","friend_chat"],"registers":["casual","polite"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":20,"prerequisite_seed_keys":["gp_ext_hazu_da","gp_nai_form"],"examples":[{"jp":"彼が約束を忘れるはずがない。","zh":"他不可能忘记约定。","scene":"friend_chat","register":"casual"},{"jp":"確認済みですから、数字が違うはずはありません。","zh":"已经确认过，数字按理不会错。","scene":"workplace","register":"polite"},{"jp":"こんな短時間で全部終わるはずがない。","zh":"不可能在这么短的时间内全部完成。","scene":"daily_life","register":"casual"}]},
  {"seed_key":"gp_ext_wake_da","grammar_point":"〜わけだ","canonical_form":"〜わけだ","sense_key":"wake_da_logical_explanation","form_group_slug":"wake","point_type":"grammar_pattern","primary_node_slug":"inference_judgment_sources","secondary_node_slugs":["reasons_and_explanations","sentence_final_nuance"],"sub_category":"归纳解释","core_meaning":"根据前文信息得出自然结论，或解释事情为何如此。","natural_translation":"难怪……／也就是说……","structure":"普通形 + わけだ；名词な/である + わけだ","usage_notes":"不是单纯原因，而是把信息整理成可理解的结论。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["没有前文依据时突然使用「わけだ」会让逻辑不完整。"],"base_type":"clause","required_form":"普通形","scenes":["daily_life","workplace","school"],"registers":["casual","polite","written"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":30,"prerequisite_seed_keys":["gp_tsumari","gp_plain_style"],"examples":[{"jp":"十年日本に住んでいるんですか。日本語が上手なわけですね。","zh":"在日本住了十年啊，难怪日语这么好。","scene":"daily_life","register":"polite"},{"jp":"今日は祝日だから、銀行が閉まっているわけだ。","zh":"今天是节假日，所以银行才关门。","scene":"daily_life","register":"casual"},{"jp":"利用者が増えたため、対応時間を延ばす必要があるわけです。","zh":"因为使用者增加，所以有必要延长服务时间。","scene":"workplace","register":"written"}]},
  {"seed_key":"gp_ext_wake_dewa_nai","grammar_point":"〜わけではない","canonical_form":"〜わけではない","sense_key":"wake_dewa_nai_partial_negation","form_group_slug":"wake","point_type":"grammar_pattern","primary_node_slug":"contrast_concession_comparison","secondary_node_slugs":["inference_judgment_sources","tense_negation"],"sub_category":"部分否定与纠正","core_meaning":"否定从前文可能推导出的过度结论，表示并非完全如此。","natural_translation":"并不是……／并非意味着……","structure":"普通形 + わけではない","usage_notes":"保留部分事实，只否定绝对化理解。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["它不是简单事实否定，而是纠正对方或前文推论。"],"base_type":"clause","required_form":"普通形","scenes":["daily_life","workplace","school"],"registers":["casual","polite","written"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":40,"prerequisite_seed_keys":["gp_ext_wake_da","gp_nai_form"],"examples":[{"jp":"甘いものが嫌いなわけではありません。","zh":"并不是讨厌甜食。","scene":"daily_life","register":"polite"},{"jp":"反対しているわけではないけど、少し心配だ。","zh":"也不是反对，只是有点担心。","scene":"workplace","register":"casual"},{"jp":"値段が高ければ品質がいいわけではありません。","zh":"并不是价格高质量就一定好。","scene":"shopping","register":"written"}]},
  {"seed_key":"gp_ext_wake_ga_nai","grammar_point":"〜わけがない","canonical_form":"〜わけがない","sense_key":"wake_ga_nai_emphatic_impossible","form_group_slug":"wake","point_type":"grammar_pattern","primary_node_slug":"inference_judgment_sources","secondary_node_slugs":["sentence_final_nuance","tense_negation"],"sub_category":"强烈不可能","core_meaning":"根据常识或说话人的确信，强烈断定某事绝不可能。","natural_translation":"怎么可能……","structure":"普通形 + わけがない","usage_notes":"口语情绪通常比「はずがない」更强，后者更偏基于事实推理。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["正式分析中避免用过于情绪化的断定。"],"base_type":"clause","required_form":"普通形","scenes":["friend_chat","daily_life","workplace"],"registers":["casual","polite"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":50,"prerequisite_seed_keys":["gp_ext_wake_da","gp_ext_hazu_ga_nai"],"examples":[{"jp":"一日で全部覚えられるわけがない。","zh":"怎么可能一天全部记住。","scene":"school","register":"casual"},{"jp":"彼がそんな失礼なことを言うわけがありません。","zh":"他不可能说那么失礼的话。","scene":"workplace","register":"polite"},{"jp":"準備なしで成功するわけがないよ。","zh":"毫无准备怎么可能成功。","scene":"friend_chat","register":"casual"}]},
  {"seed_key":"gp_ext_ni_chigainai","grammar_point":"〜に違いない","canonical_form":"〜に違いない","sense_key":"ni_chigainai_strong_inference","form_group_slug":"strong_inference","point_type":"grammar_pattern","primary_node_slug":"inference_judgment_sources","secondary_node_slugs":["sentence_final_nuance"],"sub_category":"高度确信推断","core_meaning":"根据证据或判断强烈确信某事为真。","natural_translation":"一定……／肯定……","structure":"普通形 + に違いない；名词/な形容词 + に違いない","usage_notes":"仍是推断，不是直接确认的事实；书面和叙述中常见。","practicality":"A","spoken_or_written":"both","jlpt_level":"N2","common_mistakes":["确认过的事实无需再用推断形式。"],"base_type":"clause","required_form":"普通形","scenes":["daily_life","workplace","school"],"registers":["polite","written"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":60,"prerequisite_seed_keys":["gp_ext_hazu_da","gp_you_da"],"examples":[{"jp":"電気がついている。誰かいるに違いない。","zh":"灯亮着，肯定有人。","scene":"daily_life","register":"casual"},{"jp":"この数字には入力ミスがあるに違いありません。","zh":"这个数字一定有录入错误。","scene":"workplace","register":"polite"},{"jp":"彼は長い間準備してきたに違いない。","zh":"他一定准备了很久。","scene":"school","register":"written"}]},
