  {"seed_key":"gp_ext_tatoe_temo","grammar_point":"たとえ〜ても","canonical_form":"たとえ〜ても","sense_key":"tatoe_temo_emphatic_concession","form_group_slug":"advanced_concession","point_type":"grammar_pattern","primary_node_slug":"contrast_concession_comparison","secondary_node_slugs":["conditions_and_hypotheses"],"sub_category":"强假设让步","core_meaning":"把极端或不利情况作为假设，并强调后项意志或结论不变。","natural_translation":"即使……也……","structure":"たとえ + Vて形/形容词ても/名词でも","usage_notes":"「たとえ」强化让步，后项常有意志、原则或确定判断。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["使用「たとえ」后通常需要与「ても／でも」呼应。"],"base_type":"clause","required_form":"て形条件","scenes":["daily_life","workplace","friend_chat"],"registers":["casual","polite","written"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":280,"prerequisite_seed_keys":["gp_temo"],"examples":[{"jp":"たとえ雨が降っても、試合は行います。","zh":"即使下雨，也会举行比赛。","scene":"school","register":"formal"},{"jp":"たとえ失敗しても、もう一度挑戦します。","zh":"即使失败，也会再挑战一次。","scene":"workplace","register":"polite"},{"jp":"たとえ遠くても、会いに行くよ。","zh":"即使很远，我也会去见你。","scene":"friend_chat","register":"casual"}]},
  {"seed_key":"gp_ext_ba_hodo","grammar_point":"〜ば〜ほど","canonical_form":"〜ば〜ほど","sense_key":"ba_hodo_correlated_degree","form_group_slug":"correlated_degree","point_type":"grammar_pattern","primary_node_slug":"comparison_degree_scope","secondary_node_slugs":["conditions_and_hypotheses"],"sub_category":"程度正相关","core_meaning":"表示前项程度越增加，后项也相应变化。","natural_translation":"越……越……","structure":"Vば + V辞书形 + ほど；い形容词ければ + い形容词 + ほど；名词/な形容词なら + である + ほど","usage_notes":"通常重复同一词根，描述相关变化。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["前后若无程度相关关系，不能仅因中文有“越”就套用。"],"base_type":"clause","required_form":"ば形与辞书形","scenes":["daily_life","school","workplace"],"registers":["casual","polite","written"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":290,"prerequisite_seed_keys":["gp_ext_ba_form","gp_hodo"],"examples":[{"jp":"練習すればするほど、上手になります。","zh":"越练越熟练。","scene":"school","register":"polite"},{"jp":"考えれば考えるほど、分からなくなる。","zh":"越想越不明白。","scene":"daily_life","register":"casual"},{"jp":"情報が多ければ多いほど、判断が難しくなります。","zh":"信息越多，判断越困难。","scene":"workplace","register":"written"}]},
  {"seed_key":"gp_ext_sae_ba","grammar_point":"〜さえ〜ば","canonical_form":"〜さえ〜ば","sense_key":"sae_ba_sufficient_condition","form_group_slug":"sae","point_type":"grammar_pattern","primary_node_slug":"conditions_and_hypotheses","secondary_node_slugs":["adverbial_particles","comparison_degree_scope"],"sub_category":"最低充分条件","core_meaning":"表示只要满足前项最低条件，后项就可以成立。","natural_translation":"只要……就……","structure":"名词 + さえ + 条件形；Vます去ます + さえすれば","usage_notes":"强调前项是足够条件，不代表其他条件完全不存在。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["「さえ」位置错误会改变焦点，要紧贴最低条件成分。"],"base_type":"clause","required_form":"名词或ます词干加条件形","scenes":["daily_life","workplace","travel"],"registers":["casual","polite","written"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":300,"prerequisite_seed_keys":["gp_sae_particle","gp_ext_ba_form"],"examples":[{"jp":"時間さえあれば、参加できます。","zh":"只要有时间就能参加。","scene":"workplace","register":"polite"},{"jp":"パスポートさえ持っていれば大丈夫です。","zh":"只要带着护照就没问题。","scene":"travel","register":"polite"},{"jp":"少し休みさえすれば、元気になるよ。","zh":"只要稍微休息一下就会好。","scene":"daily_life","register":"casual"}]},
  {"seed_key":"gp_ext_ni_tsurete","grammar_point":"〜につれて","canonical_form":"〜につれて","sense_key":"ni_tsurete_gradual_correlation","form_group_slug":"change_correlation","point_type":"grammar_pattern","primary_node_slug":"change_start_continuation_end","secondary_node_slugs":["time_and_sequence"],"sub_category":"自然渐进相关","core_meaning":"随着前项逐渐变化，后项也自然地同步变化。","natural_translation":"随着……","structure":"V辞书形/变化名词 + につれて","usage_notes":"前后通常都是连续、自然的程度变化，后项不宜是一次性命令。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["后项为人为单次决定时通常不自然。"],"base_type":"clause","required_form":"辞书形或变化名词","scenes":["daily_life","workplace","school"],"registers":["polite","written"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":310,"prerequisite_seed_keys":["gp_ninaru_change","gp_te_iku"],"examples":[{"jp":"年を取るにつれて、健康が気になるようになりました。","zh":"随着年龄增长，开始在意健康。","scene":"daily_life","register":"polite"},{"jp":"利用者が増えるにつれて、問い合わせも多くなりました。","zh":"随着用户增加，咨询也变多了。","scene":"workplace","register":"written"},{"jp":"授業が進むにつれて、内容が難しくなります。","zh":"随着课程推进，内容会变难。","scene":"school","register":"polite"}]},
  {"seed_key":"gp_ext_ni_shitagatte","grammar_point":"〜にしたがって","canonical_form":"〜にしたがって","sense_key":"ni_shitagatte_correlated_or_following","form_group_slug":"change_correlation","point_type":"grammar_pattern","primary_node_slug":"change_start_continuation_end","secondary_node_slugs":["compound_particles","time_and_sequence"],"sub_category":"随变化或遵照","core_meaning":"表示随着一个变化产生相关变化，或遵照规则、指示行动。","natural_translation":"随着……／按照……","structure":"V辞书形/名词 + にしたがって","usage_notes":"变化用法接近「につれて」；遵照用法的前项是规则、指示或方针。","practicality":"S","spoken_or_written":"written","jlpt_level":"N2","common_mistakes":["要通过前项名词判断是相关变化还是遵照指示。"],"base_type":"clause","required_form":"辞书形或名词","scenes":["workplace","government_office","daily_life"],"registers":["written","formal"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":320,"prerequisite_seed_keys":["gp_ext_ni_tsurete","gp_ext_ni_sotte"],"examples":[{"jp":"気温が上がるにしたがって、冷房の使用も増えます。","zh":"随着气温上升，空调使用也增加。","scene":"daily_life","register":"written"},{"jp":"担当者の指示にしたがって操作してください。","zh":"请按照负责人的指示操作。","scene":"workplace","register":"formal"},{"jp":"規則にしたがって申請書を提出してください。","zh":"请按照规定提交申请表。","scene":"government_office","register":"formal"}]},
  {"seed_key":"gp_ext_to_tomoni","grammar_point":"〜とともに","canonical_form":"〜とともに","sense_key":"to_tomoni_together_change","form_group_slug":"change_correlation","point_type":"grammar_pattern","primary_node_slug":"change_start_continuation_end","secondary_node_slugs":["additive_progression","time_and_sequence"],"sub_category":"同时并行与共同","core_meaning":"表示两个主体共同进行，或两个变化同时发生。","natural_translation":"与……一起／同时……","structure":"名词 + とともに；V辞书形 + とともに","usage_notes":"书面变化用法常接瞬间或阶段性变化，也可表示与某人共同。","practicality":"S","spoken_or_written":"written","jlpt_level":"N2","common_mistakes":["普通朋友同行用「と一緒に」更自然。"],"base_type":"clause","required_form":"名词或辞书形","scenes":["workplace","school","daily_life"],"registers":["written","formal"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":330,"prerequisite_seed_keys":["gp_to_case_particle","gp_soshite"],"examples":[{"jp":"技術の進歩とともに、働き方も変化しました。","zh":"随着技术进步，工作方式也发生了变化。","scene":"workplace","register":"written"},{"jp":"卒業とともに、故郷へ戻りました。","zh":"毕业的同时回到了故乡。","scene":"school","register":"formal"},{"jp":"家族とともに新しい生活を始めます。","zh":"与家人一起开始新的生活。","scene":"family","register":"written"}]},
  {"seed_key":"gp_ext_ni_oujite","grammar_point":"〜に応じて","canonical_form":"〜に応じて","sense_key":"ni_oujite_adapt_to","form_group_slug":"adaptive_relations","point_type":"grammar_pattern","primary_node_slug":"conditions_and_hypotheses","secondary_node_slugs":["compound_particles","comparison_degree_scope"],"sub_category":"对应调整","core_meaning":"根据对象、需求、程度或情况的不同作出相应调整。","natural_translation":"根据……／按照……相应地","structure":"名词 + に応じて","usage_notes":"强调后项会灵活对应前项差异，不是固定依据。","practicality":"S","spoken_or_written":"both","jlpt_level":"N2","common_mistakes":["固定规则依据通常用「に基づいて」，不是动态调整的「に応じて」。"],"base_type":"noun","required_form":"需求、情况或程度名词","scenes":["workplace","school","customer_service"],"registers":["business","formal","written"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":340,"prerequisite_seed_keys":["gp_baai","gp_ext_ni_sotte"],"examples":[{"jp":"お客様の希望に応じて内容を変更します。","zh":"根据客户需求调整内容。","scene":"customer_service","register":"customer"},{"jp":"経験に応じて担当する仕事を決めます。","zh":"根据经验决定负责的工作。","scene":"workplace","register":"business"},{"jp":"理解度に応じて問題の難しさを調整します。","zh":"根据理解程度调整题目难度。","scene":"school","register":"formal"}]},
  {"seed_key":"gp_ext_ni_kurabete","grammar_point":"〜に比べて","canonical_form":"〜に比べて","sense_key":"ni_kurabete_comparison","form_group_slug":"comparison_relations","point_type":"grammar_pattern","primary_node_slug":"comparison_degree_scope","secondary_node_slugs":["compound_particles"],"sub_category":"明确比较对象","core_meaning":"把前项设为比较对象，说明后项的差异。","natural_translation":"与……相比","structure":"名词 + に比べて","usage_notes":"比单纯助词「より」更适合展开完整比较说明。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["前后比较维度必须一致。"],"base_type":"noun","required_form":"比较对象名词","scenes":["daily_life","workplace","travel"],"registers":["polite","written"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":350,"prerequisite_seed_keys":["gp_yori_comparison","gp_hodo"],"examples":[{"jp":"去年に比べて、今年は雨が少ないです。","zh":"与去年相比，今年雨少。","scene":"daily_life","register":"polite"},{"jp":"旧モデルに比べて、処理速度が二倍になりました。","zh":"与旧型号相比，处理速度变成了两倍。","scene":"workplace","register":"written"},{"jp":"東京に比べて、この町は静かです。","zh":"和东京相比，这个城市很安静。","scene":"travel","register":"polite"}]},
  {"seed_key":"gp_ext_ni_totte","grammar_point":"〜にとって","canonical_form":"〜にとって","sense_key":"ni_totte_viewpoint","form_group_slug":"viewpoint_relations","point_type":"grammar_pattern","primary_node_slug":"particles_and_relations","secondary_node_slugs":["compound_particles","inference_judgment_sources"],"sub_category":"评价立场","core_meaning":"明确某个评价、价值或意义是从谁的立场而言。","natural_translation":"对……来说","structure":"人/组织 + にとって","usage_notes":"后项通常是评价、重要性或意义，不直接接受益动作。","practicality":"S","spoken_or_written":"both","jlpt_level":"N3","common_mistakes":["表示动作接收者时使用「に」，不是观点「にとって」。"],"base_type":"noun","required_form":"人物或组织名词","scenes":["daily_life","workplace","school"],"registers":["casual","polite","written"],"stage_slug":"natural_advanced_use","module_slug":"advanced_natural","sort_order":360,"prerequisite_seed_keys":["gp_ni","gp_to_omou"],"examples":[{"jp":"家族は私にとって一番大切です。","zh":"家人对我来说最重要。","scene":"family","register":"polite"},{"jp":"この経験は会社にとって大きな財産です。","zh":"这段经验对公司来说是巨大财富。","scene":"workplace","register":"business"},{"jp":"外国語を学ぶことは学生にとって重要です。","zh":"学习外语对学生来说很重要。","scene":"school","register":"written"}]},
