    ('additive_progression', 'sequence_connectors'),
    ('adversative_connections', 'contrast_connectors'),
    ('cause_result_connections', 'cause_result_connectors'),
    ('plain_polite_style', 'plain_polite_register'),
    ('in_out_hierarchy', 'social_in_out_relationships'),
    ('predicate_core', 'topic_subject_predicate'),
    ('tense_negation', 'tense_and_negation'),
    ('derived_potential_passive_causative', 'derived_forms_potential_passive_causative'),
    ('ellipsis_context_completion', 'ellipsis_context')
),
normalized_secondary_nodes AS (
  SELECT
    content.seed_key,
    COALESCE(
      array_agg(DISTINCT COALESCE(alias.canonical_slug, source.slug))
        FILTER (WHERE source.slug NOT IN ('formal', 'written', 'news')),
      '{}'::text[]
    ) AS slugs
  FROM grammar_content_seed content
  LEFT JOIN LATERAL unnest(content.secondary_node_slugs) AS source(slug) ON TRUE
  LEFT JOIN taxonomy_slug_alias alias ON alias.alias_slug = source.slug
  GROUP BY content.seed_key
)
UPDATE grammar_content_seed content
SET secondary_node_slugs = normalized.slugs
FROM normalized_secondary_nodes normalized
WHERE normalized.seed_key = content.seed_key;

WITH canonical_form_override(seed_key, canonical_form) AS (
  VALUES
    ('gp_ext_teru_contraction', '〜てる'),
    ('gp_ext_chau_jau', '〜ちゃう／〜じゃう'),
    ('gp_ext_toku_contraction', '〜とく／〜どく'),
    ('gp_ext_nakya_contraction', '〜なきゃ'),
    ('gp_ext_tteiu_contraction', '〜っていう'),
    ('gp_ext_ja_contraction', 'じゃ'),
    ('gp_ext_nakucha_contraction', '〜なくちゃ'),
    ('gp_ext_koto_ga_dekimasen', '〜ことができません')
)
UPDATE grammar_content_seed content
SET canonical_form = canonical_form_override.canonical_form
FROM canonical_form_override
WHERE canonical_form_override.seed_key = content.seed_key;

WITH prerequisite_alias(alias_seed_key, canonical_seed_key) AS (
  VALUES
    ('gp_ndesuga', 'gp_n_desu_ga'),
    ('gp_ippoude', 'gp_ippou_de'),
    ('gp_ni_suru', 'gp_nisuru_change'),
    ('gp_ni_yoruto', 'gp_ni_yoru_to'),
    ('gp_ndesu', 'gp_n_desu'),
    ('gp_te_iku', 'gp_teiku'),
    ('gp_te_kuru', 'gp_tekuru'),
    ('gp_sasete_itadakimasu', 'gp_sasete_itadaku'),
    ('gp_tte_quotation', 'gp_tte'),
    ('gp_nado_particle', 'gp_ext_nado_particle'),
    ('gp_eikyou_wo_ukeru', 'gp_eikyo_wo_ukeru'),
    ('gp_tsuzukeru', 'gp_ext_tsuzukeru')
),
normalized_prerequisites AS (
  SELECT
    content.seed_key,
    COALESCE(
      array_agg(DISTINCT COALESCE(alias.canonical_seed_key, source.seed_key))
        FILTER (WHERE source.seed_key IS NOT NULL),
      '{}'::text[]
    ) AS seed_keys
  FROM grammar_content_seed content
  LEFT JOIN LATERAL unnest(content.prerequisite_seed_keys) AS source(seed_key) ON TRUE
  LEFT JOIN prerequisite_alias alias ON alias.alias_seed_key = source.seed_key
  GROUP BY content.seed_key
)
UPDATE grammar_content_seed content
SET prerequisite_seed_keys = normalized.seed_keys
FROM normalized_prerequisites normalized
WHERE normalized.seed_key = content.seed_key;

WITH prerequisite_override(seed_key, prerequisite_seed_keys) AS (
  VALUES
    ('gp_ext_prohibitive_form', ARRAY['gp_dict_form']),
    ('gp_ext_ba_form', ARRAY['gp_plain_style']),
    ('gp_ext_i_adjective_negative', ARRAY['gp_plain_style']),
    ('gp_ext_aida', ARRAY['gp_plain_style', 'gp_main_subordinate_clause']),
    ('gp_ext_saichuu_ni', ARRAY['gp_plain_style']),
    ('gp_ext_naide_without', ARRAY['gp_nai_form', 'gp_main_subordinate_clause']),
    ('gp_ext_gofuben_wo_okake', ARRAY['gp_honorific_language', 'gp_humble_language']),
    ('gp_ext_wo_ukete', ARRAY['gp_passive_form'])
)
UPDATE grammar_content_seed content
SET prerequisite_seed_keys = prerequisite_override.prerequisite_seed_keys
FROM prerequisite_override
WHERE prerequisite_override.seed_key = content.seed_key;

DO $$
DECLARE
  invalid_primary_nodes TEXT;
  invalid_secondary_nodes TEXT;
  invalid_prerequisites TEXT;
  invalid_modules TEXT;
  incomplete_content TEXT;
BEGIN
  SELECT string_agg(content.seed_key || ':' || content.primary_node_slug, ', ')
  INTO invalid_primary_nodes
  FROM grammar_content_seed content
  LEFT JOIN taxonomy_nodes node ON node.slug = content.primary_node_slug
  WHERE node.id IS NULL;

  SELECT string_agg(content.seed_key || ':' || node_slug, ', ')
  INTO invalid_secondary_nodes
  FROM grammar_content_seed content
  CROSS JOIN LATERAL unnest(content.secondary_node_slugs) AS node_slug
  LEFT JOIN taxonomy_nodes node ON node.slug = node_slug
  WHERE node.id IS NULL;

  SELECT string_agg(content.seed_key || ':' || prerequisite_seed_key, ', ')
  INTO invalid_prerequisites
  FROM grammar_content_seed content
  CROSS JOIN LATERAL unnest(content.prerequisite_seed_keys) AS prerequisite_seed_key
  LEFT JOIN grammar_points point ON point.seed_key = prerequisite_seed_key
  LEFT JOIN grammar_content_seed future_point ON future_point.seed_key = prerequisite_seed_key
  WHERE point.id IS NULL AND future_point.seed_key IS NULL;

  SELECT string_agg(content.seed_key || ':' || content.module_slug, ', ')
  INTO invalid_modules
  FROM grammar_content_seed content
  LEFT JOIN learning_stages stage ON stage.slug = content.stage_slug
  LEFT JOIN learning_modules module
    ON module.slug = content.module_slug
   AND module.learning_stage_id = stage.id
  WHERE stage.id IS NULL OR module.id IS NULL;

  SELECT string_agg(content.seed_key, ', ')
  INTO incomplete_content
  FROM grammar_content_seed content
  WHERE NULLIF(BTRIM(content.core_meaning), '') IS NULL
     OR NULLIF(BTRIM(content.structure), '') IS NULL
     OR NULLIF(BTRIM(content.usage_notes), '') IS NULL
     OR jsonb_array_length(content.common_mistakes) < 1
     OR jsonb_array_length(content.examples) < 3
     OR cardinality(content.scenes) < 1
     OR cardinality(content.registers) < 1;

  IF invalid_primary_nodes IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid grammar primary taxonomy nodes: %', invalid_primary_nodes;
  END IF;
  IF invalid_secondary_nodes IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid grammar secondary taxonomy nodes: %', invalid_secondary_nodes;
  END IF;
  IF invalid_prerequisites IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid grammar prerequisites: %', invalid_prerequisites;
  END IF;
  IF invalid_modules IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid grammar learning modules: %', invalid_modules;
  END IF;
  IF incomplete_content IS NOT NULL THEN
    RAISE EXCEPTION 'Incomplete grammar content: %', incomplete_content;
  END IF;
END $$;

INSERT INTO grammar_points (
  seed_key,
  grammar_point,
  point_type,
  canonical_form,
  sense_key,
  form_group_slug,
  primary_taxonomy_node_id,
  status,
  reading,
  category_id,
  sub_category,
  core_meaning,
  natural_translation,
  structure,
  usage_notes,
  practicality,
  spoken_or_written,
  notes,
  jlpt_level,
  common_mistakes,
  is_mvp
)
SELECT
  content.seed_key,
  content.grammar_point,
  content.point_type,
  content.canonical_form,
  content.sense_key,
  content.form_group_slug,
  node.id,
  'active',
  content.grammar_point,
  node.legacy_category_id,
  content.sub_category,
  content.core_meaning,
  content.natural_translation,
  content.structure,
  content.usage_notes,
  content.practicality,
  content.spoken_or_written,
  content.usage_notes,
  content.jlpt_level,
  content.common_mistakes,
  TRUE
FROM grammar_content_seed content
JOIN taxonomy_nodes node ON node.slug = content.primary_node_slug
ON CONFLICT (seed_key) DO UPDATE SET
  grammar_point = EXCLUDED.grammar_point,
  point_type = EXCLUDED.point_type,
  canonical_form = EXCLUDED.canonical_form,
  sense_key = EXCLUDED.sense_key,
  form_group_slug = EXCLUDED.form_group_slug,
  primary_taxonomy_node_id = EXCLUDED.primary_taxonomy_node_id,
  status = EXCLUDED.status,
  reading = EXCLUDED.reading,
  category_id = EXCLUDED.category_id,
  sub_category = EXCLUDED.sub_category,
  core_meaning = EXCLUDED.core_meaning,
  natural_translation = EXCLUDED.natural_translation,
  structure = EXCLUDED.structure,
  usage_notes = EXCLUDED.usage_notes,
  practicality = EXCLUDED.practicality,
  spoken_or_written = EXCLUDED.spoken_or_written,
  notes = EXCLUDED.notes,
  jlpt_level = EXCLUDED.jlpt_level,
  common_mistakes = EXCLUDED.common_mistakes,
  is_mvp = EXCLUDED.is_mvp,
  updated_at = NOW();

DELETE FROM grammar_point_taxonomy_tags tags
USING grammar_points point, grammar_content_seed content
WHERE tags.grammar_point_id = point.id
  AND point.seed_key = content.seed_key;

INSERT INTO grammar_point_taxonomy_tags (grammar_point_id, taxonomy_node_id)
SELECT DISTINCT point.id, node.id
FROM grammar_content_seed content
JOIN grammar_points point ON point.seed_key = content.seed_key
CROSS JOIN LATERAL unnest(
  ARRAY[content.primary_node_slug] || content.secondary_node_slugs
) AS node_slug
JOIN taxonomy_nodes node ON node.slug = node_slug
ON CONFLICT DO NOTHING;

DELETE FROM grammar_point_connections connection
USING grammar_points point, grammar_content_seed content
WHERE connection.grammar_point_id = point.id
  AND point.seed_key = content.seed_key;

INSERT INTO grammar_point_connections (
  grammar_point_id,
  base_type,
  required_form,
  pattern,
  notes,
  sort_order
)
SELECT
  point.id,
  content.base_type,
  content.required_form,
  content.structure,
  content.usage_notes,
  1
FROM grammar_content_seed content
JOIN grammar_points point ON point.seed_key = content.seed_key;

DELETE FROM grammar_point_scene_tags tags
USING grammar_points point, grammar_content_seed content
WHERE tags.grammar_point_id = point.id
  AND point.seed_key = content.seed_key;

WITH content_scene_names AS (
  SELECT content.seed_key, scene_name
  FROM grammar_content_seed content
  CROSS JOIN LATERAL unnest(content.scenes) AS scene_name
  UNION
  SELECT content.seed_key, example.item ->> 'scene'
  FROM grammar_content_seed content
  CROSS JOIN LATERAL jsonb_array_elements(content.examples) AS example(item)
  WHERE NULLIF(example.item ->> 'scene', '') IS NOT NULL
)
INSERT INTO grammar_point_scene_tags (grammar_point_id, scene_tag_id)
SELECT DISTINCT point.id, scene.id
FROM content_scene_names content_scene
JOIN grammar_points point ON point.seed_key = content_scene.seed_key
JOIN scene_tags scene ON scene.name_en = content_scene.scene_name
ON CONFLICT DO NOTHING;

DELETE FROM grammar_point_register_tags tags
USING grammar_points point, grammar_content_seed content
WHERE tags.grammar_point_id = point.id
  AND point.seed_key = content.seed_key;

WITH content_register_names AS (
  SELECT content.seed_key, register_name
  FROM grammar_content_seed content
  CROSS JOIN LATERAL unnest(content.registers) AS register_name
  UNION
  SELECT content.seed_key, example.item ->> 'register'
  FROM grammar_content_seed content
  CROSS JOIN LATERAL jsonb_array_elements(content.examples) AS example(item)
  WHERE NULLIF(example.item ->> 'register', '') IS NOT NULL
)
INSERT INTO grammar_point_register_tags (grammar_point_id, register_tag_id)
SELECT DISTINCT point.id, register_tag.id
FROM content_register_names content_register
JOIN grammar_points point ON point.seed_key = content_register.seed_key
JOIN register_tags register_tag ON register_tag.name_en = content_register.register_name
ON CONFLICT DO NOTHING;

DELETE FROM example_sentences example
USING grammar_points point, grammar_content_seed content
WHERE example.grammar_point_id = point.id
  AND point.seed_key = content.seed_key;

INSERT INTO example_sentences (
  grammar_point_id,
  jp,
  zh,
  scene_tag_id,
  register_tag_id,
  difficulty,
  naturalness_score,
  notes
)
SELECT
  point.id,
  example.item ->> 'jp',
  example.item ->> 'zh',
  scene.id,
  register_tag.id,
  LEAST(example.ordinality::integer, 3),
  5,
  content.grammar_point || '的场景化自然例句。'
FROM grammar_content_seed content
JOIN grammar_points point ON point.seed_key = content.seed_key
CROSS JOIN LATERAL jsonb_array_elements(content.examples)
  WITH ORDINALITY AS example(item, ordinality)
LEFT JOIN scene_tags scene
  ON scene.name_en = COALESCE(example.item ->> 'scene', content.scenes[1])
LEFT JOIN register_tags register_tag
  ON register_tag.name_en = COALESCE(example.item ->> 'register', content.registers[1]);

DELETE FROM grammar_point_prerequisites relation
USING grammar_points point, grammar_content_seed content
WHERE relation.grammar_point_id = point.id
  AND point.seed_key = content.seed_key;

INSERT INTO grammar_point_prerequisites (
  grammar_point_id,
  prerequisite_grammar_point_id,
  relation_type
)
SELECT DISTINCT
  point.id,
  prerequisite.id,
  'required'
FROM grammar_content_seed content
JOIN grammar_points point ON point.seed_key = content.seed_key
CROSS JOIN LATERAL unnest(content.prerequisite_seed_keys) AS prerequisite_seed_key
JOIN grammar_points prerequisite ON prerequisite.seed_key = prerequisite_seed_key
WHERE point.id <> prerequisite.id
ON CONFLICT (grammar_point_id, prerequisite_grammar_point_id) DO UPDATE SET
  relation_type = EXCLUDED.relation_type;

