CREATE TEMP TABLE grammar_curriculum_rebuild ON COMMIT DROP AS
SELECT
  point.id AS grammar_point_id,
  COALESCE(override.stage_slug, content.stage_slug, current_stage.slug) AS stage_slug,
  COALESCE(
    override.module_slug,
    content.module_slug,
    CASE current_stage.slug
      WHEN 'foundations' THEN
        CASE
          WHEN primary_node.slug = 'particles_and_relations'
            OR primary_dimension.slug = 'particle_system'
            THEN 'core_particles'
          ELSE 'sentence_core'
        END
      WHEN 'conjugation' THEN
        CASE
          WHEN primary_node.slug = 'adjective_noun_conjugation' THEN 'adjective_noun_forms'
          WHEN primary_node.slug = 'tense_and_negation' THEN 'tense_negation'
          WHEN primary_node.slug IN ('modification_connection_nominalization', 'noun_modifying_clauses') THEN 'clause_building'
          ELSE 'verb_forms'
        END
      WHEN 'functional_patterns' THEN
        CASE
          WHEN primary_node.slug IN ('time_and_sequence', 'reasons_and_explanations', 'conditions_and_hypotheses', 'contrast_concession_comparison') THEN 'time_cause_condition'
          WHEN primary_node.slug IN ('purpose_and_plans', 'requests_permission_advice', 'obligation_necessity_unnecessity') THEN 'purpose_request_obligation'
          WHEN primary_node.slug IN ('inference_judgment_sources', 'comparison_degree_scope', 'sentence_final_nuance') THEN 'comparison_inference'
          ELSE 'quotation_information'
        END
      WHEN 'voice_aspect_benefit' THEN
        CASE
          WHEN primary_node.slug = 'giving_receiving_benefit' THEN 'giving_receiving'
          WHEN primary_node.slug IN ('ability_potential_difficulty', 'derived_potential_passive_causative') THEN 'voice_ability'
          ELSE 'aspect_experience'
        END
      ELSE
        CASE
          WHEN primary_node.slug IN ('casual_spoken_register', 'sentence_final_nuance', 'plain_polite_style') THEN 'social_conversation'
          WHEN primary_node.slug IN ('honorifics_and_politeness', 'honorific_humble_language', 'in_out_hierarchy') THEN 'workplace_service'
          WHEN primary_dimension.slug IN ('discourse_organization', 'sentence_structure') THEN 'media_formal'
          WHEN primary_dimension.slug = 'collocation_construction' THEN 'collocations_scenarios'
          ELSE 'advanced_natural'
        END
    END
  ) AS module_slug,
  COALESCE(
    override.content_order,
    content.sort_order,
    curriculum.recommended_order,
    primary_node.display_order * 100
  ) AS content_order,
  point.grammar_point
FROM grammar_points point
JOIN taxonomy_nodes primary_node ON primary_node.id = point.primary_taxonomy_node_id
JOIN taxonomy_dimensions primary_dimension ON primary_dimension.id = primary_node.dimension_id
LEFT JOIN grammar_point_curriculum curriculum ON curriculum.grammar_point_id = point.id
LEFT JOIN learning_stages current_stage ON current_stage.id = curriculum.learning_stage_id
LEFT JOIN grammar_content_seed content ON content.seed_key = point.seed_key
LEFT JOIN grammar_curriculum_override override ON override.seed_key = point.seed_key
WHERE point.status = 'active';

DELETE FROM grammar_point_curriculum curriculum
USING grammar_points point
WHERE curriculum.grammar_point_id = point.id
  AND point.status = 'active';

WITH RECURSIVE dependency_depth(grammar_point_id, depth) AS (
  SELECT point.id, 0
  FROM grammar_points point
  WHERE point.status = 'active'
  UNION ALL
  SELECT relation.grammar_point_id, dependency_depth.depth + 1
  FROM dependency_depth
  JOIN grammar_point_prerequisites relation
    ON relation.prerequisite_grammar_point_id = dependency_depth.grammar_point_id
  JOIN grammar_points dependent ON dependent.id = relation.grammar_point_id
  WHERE dependent.status = 'active'
    AND dependency_depth.depth < 30
),
point_depths AS (
  SELECT grammar_point_id, MAX(depth) AS dependency_depth
  FROM dependency_depth
  GROUP BY grammar_point_id
),
ordered AS (
  SELECT
    rebuild.grammar_point_id,
    stage.id AS learning_stage_id,
    module.id AS learning_module_id,
    stage.display_order AS level,
    row_number() OVER (
      PARTITION BY stage.id
      ORDER BY
        point_depths.dependency_depth,
        module.display_order,
        rebuild.content_order,
        rebuild.grammar_point,
        rebuild.grammar_point_id
    )::integer AS recommended_order,
    row_number() OVER (
      PARTITION BY module.id
      ORDER BY
        point_depths.dependency_depth,
        rebuild.content_order,
        rebuild.grammar_point,
        rebuild.grammar_point_id
    )::integer AS module_order
  FROM grammar_curriculum_rebuild rebuild
  JOIN learning_stages stage ON stage.slug = rebuild.stage_slug
  JOIN learning_modules module
    ON module.slug = rebuild.module_slug
   AND module.learning_stage_id = stage.id
  JOIN point_depths ON point_depths.grammar_point_id = rebuild.grammar_point_id
)
INSERT INTO grammar_point_curriculum (
  grammar_point_id,
  learning_stage_id,
  learning_module_id,
  level,
  recommended_order,
  module_order
)
SELECT
  grammar_point_id,
  learning_stage_id,
  learning_module_id,
  level,
  recommended_order,
  module_order
FROM ordered;

CREATE TEMP TABLE grammar_comparison_seed (
  slug TEXT PRIMARY KEY,
  name_zh TEXT NOT NULL,
  summary TEXT NOT NULL,
  common_meaning TEXT NOT NULL,
  decision_rules JSONB NOT NULL,
  connection_differences JSONB NOT NULL,
  register_differences JSONB NOT NULL,
  interchangeable_cases JSONB NOT NULL,
  non_interchangeable_cases JSONB NOT NULL,
  minimal_pair_examples JSONB NOT NULL,
  learner_mistakes JSONB NOT NULL,
  member_seed_keys TEXT[] NOT NULL
) ON COMMIT DROP;

INSERT INTO grammar_comparison_seed
SELECT *
FROM jsonb_populate_recordset(NULL::grammar_comparison_seed, $grammar_comparisons$
[
  {"slug":"ni_vs_e_direction","name_zh":"に vs へ（到达点与方向）","summary":"区分明确到达点和移动方向。","common_meaning":"两者都可跟移动动词表示目的地。","decision_rules":[{"conditionZh":"强调到达、进入或具体终点","preferredMemberPosition":1,"explanationZh":"「に」把地点视为动作到达点。"},{"conditionZh":"强调朝某方向移动或用于路线标识","preferredMemberPosition":2,"explanationZh":"「へ」突出朝向而非最终到达。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"地点名词 + に + 移动动词。"},{"memberPosition":2,"descriptionZh":"地点名词 + へ + 移动动词，助词读 e。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"所有语体通用。"},{"memberPosition":2,"descriptionZh":"所有语体通用，公告和方向说明中常见。"}],"interchangeable_cases":["行く、来る、帰る等移动动词的普通目的地。"],"non_interchangeable_cases":["存在地点、时间点、间接对象只能用に；へ不能替代。"],"minimal_pair_examples":[{"contextZh":"说明明天去京都","sentences":[{"memberPosition":1,"jp":"明日、京都に行きます。","zh":"明天去京都。"},{"memberPosition":2,"jp":"明日、京都へ行きます。","zh":"明天往京都去。"}],"explanationZh":"两句都自然，に更像目的地，へ更突出方向。"}],"learner_mistakes":[{"descriptionZh":"把存在句的地点「に」换成「へ」。","correctionZh":"说「京都に住んでいます」，不能说「京都へ住んでいます」。"}],"member_seed_keys":["gp_ni","gp_ext_e_particle"]},
  {"slug":"kara_origin_vs_made_limit","name_zh":"から vs まで（起点与终点）","summary":"用一组助词界定时间、地点和数量范围。","common_meaning":"两者共同建立范围边界。","decision_rules":[{"conditionZh":"标记范围从哪里或何时开始","preferredMemberPosition":1,"explanationZh":"使用起点「から」。"},{"conditionZh":"标记范围到哪里或何时结束","preferredMemberPosition":2,"explanationZh":"使用终点「まで」。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"起点名词 + から。"},{"memberPosition":2,"descriptionZh":"终点名词 + まで；不属于格助词。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"口语、书面均通用。"},{"memberPosition":2,"descriptionZh":"口语、书面均通用。"}],"interchangeable_cases":[],"non_interchangeable_cases":["起点与终点方向相反，不能直接互换。"],"minimal_pair_examples":[{"contextZh":"说明营业时间","sentences":[{"memberPosition":1,"jp":"店は九時から開きます。","zh":"店从九点开门。"},{"memberPosition":2,"jp":"店は九時まで開いています。","zh":"店开到九点。"}],"explanationZh":"から回答开始时间，まで回答结束时间。"}],"learner_mistakes":[{"descriptionZh":"把「まで」误标为格助词或与期限「までに」混淆。","correctionZh":"持续终点用まで，完成期限用までに。"}],"member_seed_keys":["gp_ext_kara_origin","gp_ext_made_limit"]},
  {"slug":"made_vs_made_ni","name_zh":"まで vs までに","summary":"区分持续终点和完成期限。","common_meaning":"都涉及一个时间边界。","decision_rules":[{"conditionZh":"动作或状态持续到该时间","preferredMemberPosition":1,"explanationZh":"使用「まで」。"},{"conditionZh":"动作必须在该时间前完成","preferredMemberPosition":2,"explanationZh":"使用「までに」。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"时间 + まで + 持续动作。"},{"memberPosition":2,"descriptionZh":"时间 + までに + 有界完成动作。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"所有语体通用。"},{"memberPosition":2,"descriptionZh":"所有语体通用，工作期限中高频。"}],"interchangeable_cases":[],"non_interchangeable_cases":["働く、待つ等持续动作与提出する、終える等完成动作选择不同。"],"minimal_pair_examples":[{"contextZh":"五点这个边界","sentences":[{"memberPosition":1,"jp":"五時まで働きます。","zh":"工作到五点。"},{"memberPosition":2,"jp":"五時までに提出します。","zh":"五点前提交。"}],"explanationZh":"一个说明持续多久，一个说明最晚何时完成。"}],"learner_mistakes":[{"descriptionZh":"所有中文“到五点”都使用まで。","correctionZh":"先判断后项是持续还是完成。"}],"member_seed_keys":["gp_ext_made_limit","gp_ext_made_ni"]},
  {"slug":"aida_vs_aida_ni","name_zh":"間 vs 間に","summary":"区分整个期间持续和期间内一次发生。","common_meaning":"都建立在一个持续的时间窗口上。","decision_rules":[{"conditionZh":"后项贯穿整个期间","preferredMemberPosition":1,"explanationZh":"使用「間」。"},{"conditionZh":"后项在期间内发生或完成一次","preferredMemberPosition":2,"explanationZh":"使用「間に」。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"持续状态 + 間。"},{"memberPosition":2,"descriptionZh":"持续状态 + 間に。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"所有语体通用。"},{"memberPosition":2,"descriptionZh":"所有语体通用。"}],"interchangeable_cases":[],"non_interchangeable_cases":["后项的持续性与有界性不同，通常不能互换。"],"minimal_pair_examples":[{"contextZh":"孩子睡觉的时间","sentences":[{"memberPosition":1,"jp":"子どもが寝ている間、静かにしていました。","zh":"孩子睡觉的整个期间都保持安静。"},{"memberPosition":2,"jp":"子どもが寝ている間に、夕食を作りました。","zh":"趁孩子睡觉做好了晚饭。"}],"explanationZh":"安静持续全程，做饭在窗口内完成。"}],"learner_mistakes":[{"descriptionZh":"忽略后项动作类型只凭中文“期间”选择。","correctionZh":"持续用間，发生或完成用間に。"}],"member_seed_keys":["gp_ext_aida","gp_ext_aida_ni"]},
  {"slug":"nagara_vs_tsutsu_aru","name_zh":"ながら vs つつある","summary":"区分同时动作和渐进变化。","common_meaning":"表面都含有动作持续感，但句法和意义不同。","decision_rules":[{"conditionZh":"同一主体一边做前项一边做后项","preferredMemberPosition":1,"explanationZh":"使用「ながら」。"},{"conditionZh":"书面描述变化正在逐渐发展","preferredMemberPosition":2,"explanationZh":"使用「つつある」。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"Vます词干 + ながら，后接主要动作。"},{"memberPosition":2,"descriptionZh":"变化动词ます词干 + つつある，直接作谓语。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"日常口语和书面均可。"},{"memberPosition":2,"descriptionZh":"正式书面、新闻和报告常用。"}],"interchangeable_cases":[],"non_interchangeable_cases":["同时进行两个动作不能用つつある；渐进社会变化不能用ながら。"],"minimal_pair_examples":[{"contextZh":"工作方式变化","sentences":[{"memberPosition":1,"jp":"音楽を聞きながら仕事をします。","zh":"边听音乐边工作。"},{"memberPosition":2,"jp":"働き方は変わりつつあります。","zh":"工作方式正在逐渐变化。"}],"explanationZh":"前者是同时动作，后者是变化进程。"}],"learner_mistakes":[{"descriptionZh":"看到中文“正在”就误用つつある。","correctionZh":"普通进行用ている，渐进变化才用つつある。"}],"member_seed_keys":["gp_ext_nagara","gp_ext_tsutsu_aru"]},
  {"slug":"you_ni_naru_vs_koto_ni_naru","name_zh":"ようになる vs ことになる","summary":"区分能力习惯变化和外部决定结果。","common_meaning":"都可译为“变成／开始”。","decision_rules":[{"conditionZh":"能力、习惯或状态逐渐发生变化","preferredMemberPosition":1,"explanationZh":"使用「ようになる」。"},{"conditionZh":"组织、情况或他人决定某项安排","preferredMemberPosition":2,"explanationZh":"使用「ことになる」。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"V辞书形/ない形 + ようになる。"},{"memberPosition":2,"descriptionZh":"V辞书形/ない形 + ことになる。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"所有语体通用。"},{"memberPosition":2,"descriptionZh":"工作安排和正式说明中高频。"}],"interchangeable_cases":[],"non_interchangeable_cases":["会说日语是能力变化；调到大阪工作是外部安排。"],"minimal_pair_examples":[{"contextZh":"工作变化","sentences":[{"memberPosition":1,"jp":"在宅勤務をするようになりました。","zh":"开始习惯性居家办公了。"},{"memberPosition":2,"jp":"来月から在宅勤務をすることになりました。","zh":"决定从下月开始居家办公。"}],"explanationZh":"一个描述实际习惯变化，一个报告决定。"}],"learner_mistakes":[{"descriptionZh":"把自己的能力进步说成外部决定。","correctionZh":"能力和习惯变化优先使用ようになる。"}],"member_seed_keys":["gp_ext_you_ni_naru","gp_ext_koto_ni_naru"]},
  {"slug":"koto_ga_dekiru_vs_potential_form","name_zh":"ことができる vs 可能形","summary":"区分分析性能力表达和动词可能形。","common_meaning":"都表示能力、条件或许可上的“能”。","decision_rules":[{"conditionZh":"正式说明、规则或前项内容较长","preferredMemberPosition":1,"explanationZh":"「ことができる」结构清楚、书面自然。"},{"conditionZh":"日常口语和简洁动作能力","preferredMemberPosition":2,"explanationZh":"动词可能形更自然紧凑。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"V辞书形 + ことができる。"},{"memberPosition":2,"descriptionZh":"按动词类别变为可能形。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"正式、书面、规则说明常用。"},{"memberPosition":2,"descriptionZh":"口语和一般礼貌高频。"}],"interchangeable_cases":["简单能力陈述中通常可互换。"],"non_interchangeable_cases":["长从句和制度说明使用ことができる更清晰。"],"minimal_pair_examples":[{"contextZh":"说明会说日语","sentences":[{"memberPosition":1,"jp":"日本語を話すことができます。","zh":"能够说日语。"},{"memberPosition":2,"jp":"日本語が話せます。","zh":"会说日语。"}],"explanationZh":"意义接近，第二句更适合日常会话。"}],"learner_mistakes":[{"descriptionZh":"把可能形和宾语助词机械组合。","correctionZh":"典型能力对象常用が，如日本語が話せる。"}],"member_seed_keys":["gp_ext_koto_ga_dekiru","gp_potential_form"]},
  {"slug":"hazu_vs_wake","name_zh":"はずだ vs わけだ","summary":"区分对事实的预期和对前文的归纳解释。","common_meaning":"都和逻辑推理有关。","decision_rules":[{"conditionZh":"根据计划或事实预测事情理应如此","preferredMemberPosition":1,"explanationZh":"使用「はずだ」表达预期。"},{"conditionZh":"根据已给信息得出“难怪／原来如此”的结论","preferredMemberPosition":2,"explanationZh":"使用「わけだ」作解释归纳。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"普通形 + はずだ。"},{"memberPosition":2,"descriptionZh":"普通形 + わけだ。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"口语和书面均可。"},{"memberPosition":2,"descriptionZh":"口语说明和书面论述均可。"}],"interchangeable_cases":[],"non_interchangeable_cases":["未来预期不能用わけだ；根据前文恍然理解不能只用はずだ。"],"minimal_pair_examples":[{"contextZh":"田中会不会到","sentences":[{"memberPosition":1,"jp":"田中さんは三時に着くはずです。","zh":"田中应该三点到。"},{"memberPosition":2,"jp":"三時の電車だったんですね。遅いわけです。","zh":"原来是三点的车，难怪晚。"}],"explanationZh":"一个预测到达，一个解释已经观察到的晚。"}],"learner_mistakes":[{"descriptionZh":"把中文“应该”一律翻译成はず。","correctionZh":"先区分预期、义务和解释。"}],"member_seed_keys":["gp_ext_hazu_da","gp_ext_wake_da"]},
  {"slug":"noni_monono_nimokakawarazu","name_zh":"のに vs ものの vs にもかかわらず","summary":"按情绪、书面程度和反差强度选择让步表达。","common_meaning":"都表达实际结果违背前项预期。","decision_rules":[{"conditionZh":"口语表达遗憾、惊讶或责怪","preferredMemberPosition":1,"explanationZh":"使用带情绪的「のに」。"},{"conditionZh":"报告中客观承认事实后指出限制","preferredMemberPosition":2,"explanationZh":"使用书面「ものの」。"},{"conditionZh":"强调即便在强条件下仍出现反预期结果","preferredMemberPosition":3,"explanationZh":"使用反差更强的「にもかかわらず」。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"普通形 + のに。"},{"memberPosition":2,"descriptionZh":"普通形 + ものの。"},{"memberPosition":3,"descriptionZh":"普通形/名词 + にもかかわらず。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"口语、高情绪。"},{"memberPosition":2,"descriptionZh":"正式书面、客观。"},{"memberPosition":3,"descriptionZh":"正式书面，反差最强。"}],"interchangeable_cases":["部分客观反差句中可替换，但情绪和强度变化明显。"],"non_interchangeable_cases":["句末省略表达抱怨时通常只有のに自然。"],"minimal_pair_examples":[{"contextZh":"下雨但仍有人参加","sentences":[{"memberPosition":1,"jp":"雨なのに、来てくれた。","zh":"明明下雨还来了。"},{"memberPosition":2,"jp":"雨ではあったものの、多くの人が参加した。","zh":"虽有降雨，但很多人参加了。"},{"memberPosition":3,"jp":"大雨にもかかわらず、多くの人が参加した。","zh":"尽管下着大雨，仍有很多人参加。"}],"explanationZh":"从个人感受逐步变为客观书面和强让步。"}],"learner_mistakes":[{"descriptionZh":"在正式报告中过多使用带抱怨感的のに。","correctionZh":"客观限制优先ものの，强反差用にもかかわらず。"}],"member_seed_keys":["gp_noni","gp_ext_monono","gp_ext_ni_mokakawarazu"]},
  {"slug":"te_itadakemasu_vs_te_itadakenai","name_zh":"ていただけますか vs ていただけないでしょうか","summary":"按对象关系和请求负担选择郑重程度。","common_meaning":"都以授受视角礼貌请求对方行动。","decision_rules":[{"conditionZh":"一般正式请求，负担较小且关系正常","preferredMemberPosition":1,"explanationZh":"「ていただけますか」清楚礼貌。"},{"conditionZh":"请求负担较大、对象是客户上级或需更委婉","preferredMemberPosition":2,"explanationZh":"否定可能疑问进一步降低强迫感。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"Vて + いただけますか。"},{"memberPosition":2,"descriptionZh":"Vて + いただけないでしょうか。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"一般礼貌到商务。"},{"memberPosition":2,"descriptionZh":"商务、正式、委婉。"}],"interchangeable_cases":["多数商务请求可互换，但距离和负担感不同。"],"non_interchangeable_cases":["紧急明确指令不宜过度委婉。"],"minimal_pair_examples":[{"contextZh":"请求调整日程","sentences":[{"memberPosition":1,"jp":"日程を変更していただけますか。","zh":"能请您更改日程吗？"},{"memberPosition":2,"jp":"日程を変更していただけないでしょうか。","zh":"不知能否请您更改日程？"}],"explanationZh":"第二句对对方负担的顾虑更明显。"}],"learner_mistakes":[{"descriptionZh":"认为句中有否定所以是在拒绝。","correctionZh":"整体是更委婉的请求。"}],"member_seed_keys":["gp_te_itadakemasu_ka","gp_ext_te_itadakenai_deshouka"]},
  {"slug":"honorific_rareru_vs_o_go_ninaru","name_zh":"尊敬られる vs お／ご〜になる","summary":"选择两种生产性尊敬语形式。","common_meaning":"都抬高对方或第三者的动作。","decision_rules":[{"conditionZh":"希望简洁表达或动词不适合お／ご构式","preferredMemberPosition":1,"explanationZh":"使用尊敬「られる」。"},{"conditionZh":"常见和语／汉语动作且需更明确郑重","preferredMemberPosition":2,"explanationZh":"使用「お／ご〜になる」。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"按被动形规则活用，意义由主语身份判断。"},{"memberPosition":2,"descriptionZh":"お + ます词干 + になる；ご + 汉语词干 + になる。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"一般礼貌、商务。"},{"memberPosition":2,"descriptionZh":"商务、正式，尊敬标记更显性。"}],"interchangeable_cases":["部分常见动作可替换，如読まれる／お読みになる。"],"non_interchangeable_cases":["已有特殊尊敬语时通常优先いらっしゃる、おっしゃる等。"],"minimal_pair_examples":[{"contextZh":"询问部长是否阅读资料","sentences":[{"memberPosition":1,"jp":"部長は資料を読まれましたか。","zh":"部长读资料了吗？"},{"memberPosition":2,"jp":"部長は資料をお読みになりましたか。","zh":"部长读资料了吗？"}],"explanationZh":"两句都是尊敬语，第二句形式更明确。"}],"learner_mistakes":[{"descriptionZh":"说成「お読みになられる」形成二重敬语。","correctionZh":"选择一个尊敬构式即可。"}],"member_seed_keys":["gp_rareru_honorific","gp_ext_o_go_ninaru"]},
  {"slug":"sou_rashii_to_sareru","name_zh":"そうだ（传闻）vs らしい vs とされる","summary":"按信息来源、说话人判断和文本体裁选择转述形式。","common_meaning":"都可传递并非说话人直接确认的信息。","decision_rules":[{"conditionZh":"明确转述刚获得的消息，不加入判断","preferredMemberPosition":1,"explanationZh":"使用传闻「そうだ」。"},{"conditionZh":"根据传闻或迹象作较口语的间接判断","preferredMemberPosition":2,"explanationZh":"使用「らしい」。"},{"conditionZh":"新闻、研究中表达一般认定且不突出具体来源","preferredMemberPosition":3,"explanationZh":"使用「とされる」。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"普通形 + そうだ。"},{"memberPosition":2,"descriptionZh":"普通形 + らしい。"},{"memberPosition":3,"descriptionZh":"普通形 + とされる。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"口语和一般书面。"},{"memberPosition":2,"descriptionZh":"口语、较自然。"},{"memberPosition":3,"descriptionZh":"正式书面、新闻、学术。"}],"interchangeable_cases":[],"non_interchangeable_cases":["新闻的一般认定不能直接当成朋友间听说；眼前样态そうだ不是成员。"],"minimal_pair_examples":[{"contextZh":"明天可能下雨","sentences":[{"memberPosition":1,"jp":"天気予報では、明日は雨だそうです。","zh":"天气预报说明天下雨。"},{"memberPosition":2,"jp":"明日は雨らしいです。","zh":"听说明天下雨。"},{"memberPosition":3,"jp":"明日は広い範囲で雨になるとされています。","zh":"据认为明天大范围有雨。"}],"explanationZh":"来源明确度和文本正式度逐步变化。"}],"learner_mistakes":[{"descriptionZh":"把样态そうだ的接续用于传闻。","correctionZh":"传闻直接接完整普通形，样态接词干。"}],"member_seed_keys":["gp_sou_da_hearsay","gp_rashii","gp_ext_to_sareru"]},
  {"slug":"ni_tsurete_shitagatte_tomonai","name_zh":"につれて vs にしたがって vs に伴い","summary":"区分自然相关、遵照／相关和正式伴随变化。","common_meaning":"都能表达一个变化带来另一个变化。","decision_rules":[{"conditionZh":"两个程度自然、渐进地同步变化","preferredMemberPosition":1,"explanationZh":"「につれて」最自然。"},{"conditionZh":"描述相关变化或遵照规则行动","preferredMemberPosition":2,"explanationZh":"「にしたがって」兼有两种功能。"},{"conditionZh":"制度、规模等正式变化带来相关改变","preferredMemberPosition":3,"explanationZh":"「に伴い」书面正式。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"辞书形/变化名词 + につれて。"},{"memberPosition":2,"descriptionZh":"辞书形/名词 + にしたがって。"},{"memberPosition":3,"descriptionZh":"辞书形/名词 + に伴い。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"一般说明和书面。"},{"memberPosition":2,"descriptionZh":"书面、规则说明。"},{"memberPosition":3,"descriptionZh":"正式书面、新闻。"}],"interchangeable_cases":["纯粹渐进变化中前两者有时可替换。"],"non_interchangeable_cases":["“按照指示”只能用にしたがって；正式制度变更常用に伴い。"],"minimal_pair_examples":[{"contextZh":"人数增加和工作增加","sentences":[{"memberPosition":1,"jp":"利用者が増えるにつれて、仕事も増えた。","zh":"随着用户增加，工作也增加了。"},{"memberPosition":2,"jp":"利用者の増加にしたがって、仕事も増えた。","zh":"随着用户增加，工作也增加了。"},{"memberPosition":3,"jp":"利用者の増加に伴い、窓口を増設した。","zh":"伴随用户增加，增设了窗口。"}],"explanationZh":"第三句更正式且后项是组织措施。"}],"learner_mistakes":[{"descriptionZh":"把所有“随着”都当作完全可互换。","correctionZh":"判断是否自然渐进、遵照规则或正式制度伴随。"}],"member_seed_keys":["gp_ext_ni_tsurete","gp_ext_ni_shitagatte","gp_ext_ni_tomonai"]},
  {"slug":"dake_bakari_dokoroka","name_zh":"だけでなく vs ばかりか vs どころか","summary":"按普通追加、递进和反预期选择“不仅”。","common_meaning":"都能扩大前项范围。","decision_rules":[{"conditionZh":"中性表达不仅 A 而且 B","preferredMemberPosition":1,"explanationZh":"使用「だけでなく」。"},{"conditionZh":"书面表达 B 比 A 更进一步","preferredMemberPosition":2,"explanationZh":"使用递进「ばかりか」。"},{"conditionZh":"事实与 A 的预期相反，甚至达到 B","preferredMemberPosition":3,"explanationZh":"使用「どころか」。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"普通形/名词 + だけでなく。"},{"memberPosition":2,"descriptionZh":"普通形/名词 + ばかりか。"},{"memberPosition":3,"descriptionZh":"普通形/名词 + どころか。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"口语和书面通用。"},{"memberPosition":2,"descriptionZh":"正式书面。"},{"memberPosition":3,"descriptionZh":"口语、书面均可，强调反差。"}],"interchangeable_cases":[],"non_interchangeable_cases":["无递进时不能用ばかりか；无反预期时不能用どころか。"],"minimal_pair_examples":[{"contextZh":"描述药物效果","sentences":[{"memberPosition":1,"jp":"この薬は熱だけでなく、痛みにも効きます。","zh":"这种药不仅退烧，也止痛。"},{"memberPosition":2,"jp":"この薬は効果がないばかりか、副作用もあります。","zh":"这种药不但没效果，还有副作用。"},{"memberPosition":3,"jp":"良くなるどころか、症状が悪化しました。","zh":"非但没变好，症状反而恶化了。"}],"explanationZh":"分别是中性追加、负面递进和反预期。"}],"learner_mistakes":[{"descriptionZh":"只依据中文“不仅”随机选择。","correctionZh":"先判断后项是追加、升级还是反转。"}],"member_seed_keys":["gp_ext_dake_de_naku","gp_ext_bakari_ka","gp_ext_dokoroka"]},
  {"slug":"tame_ni_yori_ni_tsuki","name_zh":"ため vs により vs につき（正式原因）","summary":"按句法完整度、正式程度和文本类型选择原因表达。","common_meaning":"都可在正式文本中表示原因。","decision_rules":[{"conditionZh":"完整句中客观说明原因及结果","preferredMemberPosition":1,"explanationZh":"「ため」最通用。"},{"conditionZh":"公告、新闻中表示客观原因、手段或依据","preferredMemberPosition":2,"explanationZh":"使用「により」。"},{"conditionZh":"告示标题式简洁说明原因","preferredMemberPosition":3,"explanationZh":"使用「につき」。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"普通形/名词の + ため。"},{"memberPosition":2,"descriptionZh":"名词 + により。"},{"memberPosition":3,"descriptionZh":"名词 + につき。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"正式说明、书面。"},{"memberPosition":2,"descriptionZh":"正式书面、新闻、公告。"},{"memberPosition":3,"descriptionZh":"高度简洁的告示和通知。"}],"interchangeable_cases":["名词性客观原因在正式文本中有时可替换，但句式自然度不同。"],"non_interchangeable_cases":["私人会话理由不宜使用により或につき。"],"minimal_pair_examples":[{"contextZh":"说明装修停业","sentences":[{"memberPosition":1,"jp":"改装工事のため、休業します。","zh":"因装修工程停业。"},{"memberPosition":2,"jp":"改装工事により、営業を休止します。","zh":"由于装修工程，暂停营业。"},{"memberPosition":3,"jp":"店内改装につき、休業いたします。","zh":"因店内装修，暂停营业。"}],"explanationZh":"从完整原因句逐步变为公告体。"}],"learner_mistakes":[{"descriptionZh":"朋友请假时使用告示体につき。","correctionZh":"私人礼貌说明使用ので更自然。"}],"member_seed_keys":["gp_tame","gp_ext_ni_yori_formal_cause","gp_ext_ni_tsuki_notice"]},
  {"slug":"yo_ne_yone","name_zh":"よ vs ね vs よね","summary":"区分告知、共感确认和带判断的确认。","common_meaning":"都调节说话人与听话人对信息的共有程度。","decision_rules":[{"conditionZh":"说话人向对方提供新信息或提醒","preferredMemberPosition":1,"explanationZh":"使用「よ」。"},{"conditionZh":"邀请对方共享感受或轻确认","preferredMemberPosition":2,"explanationZh":"使用「ね」。"},{"conditionZh":"说话人已有判断，希望对方确认同意","preferredMemberPosition":3,"explanationZh":"使用「よね」。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"句末 + よ。"},{"memberPosition":2,"descriptionZh":"句末 + ね。"},{"memberPosition":3,"descriptionZh":"句末 + よね。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"口语；正式对象需控制强度。"},{"memberPosition":2,"descriptionZh":"口语、柔和。"},{"memberPosition":3,"descriptionZh":"口语确认，共识压力略强。"}],"interchangeable_cases":[],"non_interchangeable_cases":["纯新信息不用ね；完全开放的共感不一定需要よね。"],"minimal_pair_examples":[{"contextZh":"谈论会议时间","sentences":[{"memberPosition":1,"jp":"会議は三時からですよ。","zh":"会议是三点开始哦。"},{"memberPosition":2,"jp":"会議は三時からですね。","zh":"会议是三点开始，对吧。"},{"memberPosition":3,"jp":"会議は三時からですよね。","zh":"会议是三点开始，对吧。"}],"explanationZh":"分别假设对方不知道、共同核对、以及说话人已有判断求确认。"}],"learner_mistakes":[{"descriptionZh":"在正式沟通中用よね逼迫对方赞同。","correctionZh":"需要明确确认时直接使用确认疑问句。"}],"member_seed_keys":["gp_ext_yo_final","gp_ext_ne_final","gp_yo_ne"]},
  {"slug":"de_yoroshii_vs_temo_yoroshii","name_zh":"でよろしいでしょうか vs てもよろしいでしょうか","summary":"区分确认对方选择和询问己方行动许可。","common_meaning":"都使用郑重的「よろしいでしょうか」。","decision_rules":[{"conditionZh":"确认名词性选项、数量或内容是否正确","preferredMemberPosition":1,"explanationZh":"使用「でよろしいでしょうか」。"},{"conditionZh":"询问自己或己方是否可以做某动作","preferredMemberPosition":2,"explanationZh":"使用「てもよろしいでしょうか」。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"名词 + でよろしいでしょうか。"},{"memberPosition":2,"descriptionZh":"Vて + もよろしいでしょうか。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"客服、商务确认。"},{"memberPosition":2,"descriptionZh":"客服、商务、正式许可询问。"}],"interchangeable_cases":[],"non_interchangeable_cases":["一个确认对方内容，一个询问己方动作许可，主客体不同。"],"minimal_pair_examples":[{"contextZh":"酒店前台沟通","sentences":[{"memberPosition":1,"jp":"お部屋は禁煙でよろしいでしょうか。","zh":"房间选无烟房可以吗？"},{"memberPosition":2,"jp":"お荷物をこちらでお預かりしてもよろしいでしょうか。","zh":"可以把您的行李寄存在这里吗？"}],"explanationZh":"第一句确认选项，第二句询问前台行动许可。"}],"learner_mistakes":[{"descriptionZh":"用てもよろしいでしょうか要求客户行动。","correctionZh":"请求客户行动使用ていただけますか等请求构式。"}],"member_seed_keys":["gp_ext_de_yoroshii_deshouka","gp_ext_temo_yoroshii_deshouka"]},
  {"slug":"kanemasu_vs_koto_ga_dekimasen","name_zh":"かねます vs ことができません","summary":"区分立场上的委婉拒绝和客观条件上的不可用。","common_meaning":"都可向对方说明无法满足请求。","decision_rules":[{"conditionZh":"己方从规则、立场或判断上难以接受","preferredMemberPosition":1,"explanationZh":"使用委婉拒绝「かねます」。"},{"conditionZh":"系统、制度或客观条件不允许","preferredMemberPosition":2,"explanationZh":"使用客观说明「ことができません」。"}],"connection_differences":[{"memberPosition":1,"descriptionZh":"Vます词干 + かねます。"},{"memberPosition":2,"descriptionZh":"V辞书形 + ことができません。"}],"register_differences":[{"memberPosition":1,"descriptionZh":"商务、客服、正式拒绝。"},{"memberPosition":2,"descriptionZh":"正式规则、功能说明。"}],"interchangeable_cases":["部分服务拒绝中都可使用，但责任呈现不同。"],"non_interchangeable_cases":["纯物理功能不可用不宜说かねます；组织立场拒绝不应假装成客观不能。"],"minimal_pair_examples":[{"contextZh":"说明退款不可行","sentences":[{"memberPosition":1,"jp":"お客様都合の返品には応じかねます。","zh":"因顾客原因的退货恕难接受。"},{"memberPosition":2,"jp":"使用後の商品は返品することができません。","zh":"使用后的商品不能退货。"}],"explanationZh":"第一句是组织立场，第二句陈述规则条件。"}],"learner_mistakes":[{"descriptionZh":"用客观不能句式隐藏己方选择。","correctionZh":"需要拒绝时说明立场、理由并提供替代方案。"}],"member_seed_keys":["gp_ext_kanemasu","gp_ext_koto_ga_dekimasen"]}
]
$grammar_comparisons$::jsonb);

INSERT INTO comparison_sets (
  slug,
  name_zh,
  summary,
  common_meaning,
  decision_rules,
  connection_differences,
  register_differences,
  interchangeable_cases,
  non_interchangeable_cases,
  minimal_pair_examples,
  learner_mistakes,
  status
)
SELECT
  slug,
  name_zh,
  summary,
  common_meaning,
  decision_rules,
  connection_differences,
  register_differences,
  interchangeable_cases,
  non_interchangeable_cases,
  minimal_pair_examples,
  learner_mistakes,
  'active'
FROM grammar_comparison_seed
ON CONFLICT (slug) DO UPDATE SET
  name_zh = EXCLUDED.name_zh,
  summary = EXCLUDED.summary,
  common_meaning = EXCLUDED.common_meaning,
  decision_rules = EXCLUDED.decision_rules,
  connection_differences = EXCLUDED.connection_differences,
  register_differences = EXCLUDED.register_differences,
  interchangeable_cases = EXCLUDED.interchangeable_cases,
  non_interchangeable_cases = EXCLUDED.non_interchangeable_cases,
  minimal_pair_examples = EXCLUDED.minimal_pair_examples,
  learner_mistakes = EXCLUDED.learner_mistakes,
  status = EXCLUDED.status,
  updated_at = NOW();

DELETE FROM comparison_set_members member
USING comparison_sets comparison, grammar_comparison_seed seed
WHERE member.comparison_set_id = comparison.id
  AND comparison.slug = seed.slug;

INSERT INTO comparison_set_members (
  comparison_set_id,
  grammar_point_id,
  sort_order
)
SELECT
  comparison.id,
  point.id,
  member.ordinality::integer
FROM grammar_comparison_seed seed
JOIN comparison_sets comparison ON comparison.slug = seed.slug
CROSS JOIN LATERAL unnest(seed.member_seed_keys)
  WITH ORDINALITY AS member(seed_key, ordinality)
JOIN grammar_points point ON point.seed_key = member.seed_key;

COMMIT;
